import { defineStore } from 'pinia'
import { ref, computed } from 'vue'
import { getMe, postLogin, postSwitchTenant } from "@/api/generated";

interface TenantBrief {
  id: number
  name: string
  slug: string
}

interface UserInfo {
  id: number
  login: string
  name: string
  role: 'admin' | 'manager' | 'tech' | 'field_tech'
  is_active: boolean
  tenant_id: number
  tenant_name: string
  tenant_slug: string
  tenants: TenantBrief[]
  email?: string
  phone?: string
  note?: string
  avatar_url?: string
}

export const useAuthStore = defineStore('auth', () => {
  const token = ref(localStorage.getItem('token') || '')
  const user = ref<UserInfo | null>(null)

  const isAuthenticated = computed(() => !!token.value)
  const role = computed(() => user.value?.role || null)
  const isFieldTech = computed(() => user.value?.role === 'field_tech')
  const isReadOnly = computed(() => user.value?.role === 'field_tech')
  const tenantId = computed(() => user.value?.tenant_id || null)
  const tenantName = computed(() => user.value?.tenant_name || null)
  const tenants = computed(() => user.value?.tenants || [])
  const hasMultipleTenants = computed(() => (user.value?.tenants?.length || 0) > 1)

  async function login(loginStr: string, password: string) {
    const { data, error } = await postLogin({ body: { login: loginStr, password } })
    if (error || !data?.token) {
      // error?.error — текст от бэкенда ("invalid credentials").
      // Фолбэк — если бэкенд вернул не-JSON (502/504/контейнер перезапускается).
      const msg = error?.error
      if (msg === 'invalid credentials') throw new Error('Неверный логин или пароль')
      throw new Error(msg ? msg : 'Сервер недоступен, попробуйте позже')
    }
    token.value = data.token
    localStorage.setItem('token', data.token)
    await fetchMe()
  }

  async function fetchMe() {
    const { data, error } = await getMe()
    if (error || !data) {
      logout()
      return
    }
    user.value = data as UserInfo
  }

  async function switchTenant(tenantIdValue: number) {
    const { data, error } = await postSwitchTenant({ body: { tenant_id: tenantIdValue } })
    if (error || !data?.token) {
      throw new Error(error?.error || 'Не удалось переключить тенант')
    }
    token.value = data.token
    localStorage.setItem('token', data.token)
    await fetchMe()
  }

  function logout() {
    token.value = ''
    user.value = null
    localStorage.removeItem('token')
  }

  // Try to restore session on init
  async function init() {
    if (token.value) {
      await fetchMe()
    }
  }

  return {
    token, user, isAuthenticated, role, isFieldTech, isReadOnly,
    tenantId, tenantName, tenants, hasMultipleTenants,
    login, logout, fetchMe, switchTenant, init,
  }
})

