import { ref, computed, type Ref, type ComputedRef } from 'vue'
import {
  getWazzupClientMessages,
  postCallsSms,
  postWazzupSend,
  getMessageTemplates,
} from '@/api/generated'

// Communications-домен ClientCardPage: WhatsApp send/messages/templates,
// SMS send, амоCRM Talks (для contactHasTalk-индикатора), Calls (load
// list + audio playback). Mail — отдельный домен (useClientMail).

export interface Talk {
  id: number; contact_id: number; entity_id: number; chat_id: string
  status: string; origin: string; is_read: boolean
  contact_name: string; contact_phone: string
  amo_created_at?: string; amo_updated_at?: string
}

export interface WaMessage {
  id: number; chat_id: string; direction: string; text: string
  status: string; trigger_type: string; created_at: string
}

export interface WaTemplate {
  id: number; name: string; text: string
}

export interface WaContact {
  id: number; name?: string; phone?: string; whatsapp?: string
}

export interface SmsContact {
  id: number; name?: string; phone?: string
}

export interface CallRecord {
  id: string; direction: string
  client_number: string; client_name: string
  start_time: string; duration: number
  answered: boolean; recording_url?: string
}

export interface TemplateContext {
  contactName?: string
  contactPhone?: string
  clientInn?: string
  clientName?: string
  clientEmail?: string
}

export type SendResult = { ok: true } | { ok: false; message: string }

export interface UseClientCommsResult {
  // Talks
  talks: Ref<Talk[]>
  contactHasTalk: (contactId: number) => boolean

  // WhatsApp send
  showWaSend: Ref<boolean>
  waSending: Ref<boolean>
  waText: Ref<string>
  waPhone: Ref<string>
  waContact: Ref<WaContact | null>
  waFiles: Ref<{ name: string; url: string }[]>
  waMessages: Ref<WaMessage[]>
  loadWaMessages: (clientId: number) => Promise<void>
  sendWhatsapp: (clientId: number) => Promise<SendResult>
  onWaFileSelect: (e: Event) => void

  // Templates
  waTemplates: Ref<WaTemplate[]>
  loadWaTemplates: () => Promise<void>
  applyWaTemplate: (t: WaTemplate, ctx: TemplateContext) => void

  // SMS send
  showSmsSend: Ref<boolean>
  smsSending: Ref<boolean>
  smsText: Ref<string>
  smsPhone: Ref<string>
  smsContact: Ref<SmsContact | null>
  sendSms: () => Promise<SendResult>

  // Calls
  calls: Ref<CallRecord[]>
  callsPage: Ref<number>
  callsTotalPages: ComputedRef<number>
  callsPaged: ComputedRef<CallRecord[]>
  playingCallId: Ref<string | null>
  loadingCallId: Ref<string | null>
  callProgress: Ref<string>
  toggleCall: (c: CallRecord) => void
  stopCall: () => void
}

const CALLS_PER_PAGE = 5

function formatAudioTime(sec: number): string {
  const m = Math.floor(sec / 60)
  const s = Math.floor(sec % 60)
  return `${m}:${s.toString().padStart(2, '0')}`
}

export function useClientComms(): UseClientCommsResult {
  // Talks
  const talks = ref<Talk[]>([])
  function contactHasTalk(contactId: number): boolean {
    return talks.value.some((t) => t.contact_id === contactId)
  }

  // WhatsApp send
  const showWaSend = ref<boolean>(false)
  const waSending = ref<boolean>(false)
  const waText = ref<string>('')
  const waPhone = ref<string>('')
  const waContact = ref<WaContact | null>(null)
  const waFiles = ref<{ name: string; url: string }[]>([])
  const waMessages = ref<WaMessage[]>([])

  function onWaFileSelect(e: Event): void {
    const input = e.target as HTMLInputElement
    if (!input.files) return
    for (const f of Array.from(input.files)) {
      waFiles.value.push({ name: f.name, url: URL.createObjectURL(f) })
    }
    input.value = ''
  }

  async function loadWaMessages(clientId: number): Promise<void> {
    const { data } = await getWazzupClientMessages({ query: { client_id: clientId } })
    if (data) waMessages.value = data as WaMessage[]
  }

  async function sendWhatsapp(clientId: number): Promise<SendResult> {
    if (!waText.value || !waPhone.value) return { ok: false, message: 'Пустое сообщение или телефон' }
    waSending.value = true
    try {
      const { error } = await postWazzupSend({ body: {
                client_id: clientId,
                contact_id: waContact.value?.id || 0,
                phone: waPhone.value,
                text: waText.value,
              } })
      if (error) return { ok: false, message: 'Ошибка отправки' }
      showWaSend.value = false
      await loadWaMessages(clientId)
      return { ok: true }
    } finally {
      waSending.value = false
    }
  }

  // Templates
  const waTemplates = ref<WaTemplate[]>([])

  async function loadWaTemplates(): Promise<void> {
    const { data } = await getMessageTemplates()
    if (data) waTemplates.value = data as WaTemplate[]
  }

  function applyWaTemplate(t: WaTemplate, ctx: TemplateContext): void {
    let text = t.text
    text = text.replace(/\{\{contact_name\}\}/g, ctx.contactName ?? '')
    text = text.replace(/\{\{contact_phone\}\}/g, ctx.contactPhone ?? '')
    text = text.replace(/\{\{client_inn\}\}/g, ctx.clientInn ?? '')
    text = text.replace(/\{\{client_name\}\}/g, ctx.clientName ?? '')
    text = text.replace(/\{\{client_email\}\}/g, ctx.clientEmail ?? '')
    waText.value = text
  }

  // SMS send
  const showSmsSend = ref<boolean>(false)
  const smsSending = ref<boolean>(false)
  const smsText = ref<string>('')
  const smsPhone = ref<string>('')
  const smsContact = ref<SmsContact | null>(null)

  async function sendSms(): Promise<SendResult> {
    if (!smsText.value || !smsPhone.value) return { ok: false, message: 'Пустое сообщение или телефон' }
    smsSending.value = true
    try {
      const { error } = await postCallsSms({ body: { phone: smsPhone.value, text: smsText.value } })
      if (error) return { ok: false, message: 'Ошибка отправки SMS' }
      showSmsSend.value = false
      return { ok: true }
    } finally {
      smsSending.value = false
    }
  }

  // Calls
  const calls = ref<CallRecord[]>([])
  const callsPage = ref<number>(1)
  const callsTotalPages = computed<number>(() => Math.max(1, Math.ceil(calls.value.length / CALLS_PER_PAGE)))
  const callsPaged = computed<CallRecord[]>(() => {
    const start = (callsPage.value - 1) * CALLS_PER_PAGE
    return calls.value.slice(start, start + CALLS_PER_PAGE)
  })
  const playingCallId = ref<string | null>(null)
  const loadingCallId = ref<string | null>(null)
  const callProgress = ref<string>('')
  let callAudio: HTMLAudioElement | null = null
  let callProgressTimer: ReturnType<typeof setInterval> | null = null

  function stopCall(): void {
    if (callAudio) {
      callAudio.pause()
      callAudio.src = ''
      callAudio = null
    }
    if (callProgressTimer) {
      clearInterval(callProgressTimer)
      callProgressTimer = null
    }
    playingCallId.value = null
    loadingCallId.value = null
    callProgress.value = ''
  }

  function toggleCall(c: CallRecord): void {
    if (playingCallId.value === c.id) {
      stopCall()
      return
    }
    stopCall()
    if (!c.recording_url) return
    loadingCallId.value = c.id
    callAudio = new Audio(c.recording_url)
    callAudio.addEventListener(
      'canplay',
      () => {
        loadingCallId.value = null
        playingCallId.value = c.id
        callAudio?.play()
        callProgressTimer = setInterval(() => {
          if (callAudio) {
            callProgress.value = `${formatAudioTime(callAudio.currentTime)} / ${formatAudioTime(callAudio.duration || 0)}`
          }
        }, 500)
      },
      { once: true },
    )
    callAudio.addEventListener('ended', () => stopCall(), { once: true })
    callAudio.addEventListener('error', () => stopCall(), { once: true })
    callAudio.load()
  }

  return {
    talks, contactHasTalk,
    showWaSend, waSending, waText, waPhone, waContact, waFiles, waMessages,
    loadWaMessages, sendWhatsapp, onWaFileSelect,
    waTemplates, loadWaTemplates, applyWaTemplate,
    showSmsSend, smsSending, smsText, smsPhone, smsContact, sendSms,
    calls, callsPage, callsTotalPages, callsPaged,
    playingCallId, loadingCallId, callProgress,
    toggleCall, stopCall,
  }
}

import { ref, computed, type Ref, type ComputedRef } from 'vue'
import { postOfdCreateCabinet, getOfdCabinetStatusByInn } from '@/api/generated'

// OFD кабинет: создание + polling статуса.
// Status грамматика бэкенда:
//   "step:<key>"  — текущий шаг wizard'а
//   "error:<key>:<msg>" — упал на конкретном шаге
//   "confirmed" | "exists" — финальное успешное состояние
// Шаги фронтенда (UI wizard) — фиксированный список ниже; ключи матчатся
// с backend ofd-create-cabinet state machine.

interface OfdStepDef { key: string; label: string }
export interface OfdStep extends OfdStepDef {
  state: 'done' | 'active' | 'error' | 'pending'
}

const OFD_STEP_DEFS: ReadonlyArray<OfdStepDef> = [
  { key: 'mailbox',      label: 'Создание почтового ящика' },
  { key: 'ofd_api',      label: 'Регистрация в OFD.ru' },
  { key: 'wait_email',   label: 'Ожидание письма подтверждения' },
  { key: 'activating',   label: 'Активация ссылки' },
  { key: 'set_password', label: 'Запрос кода смены пароля' },
  { key: 'wait_code',    label: 'Установка пароля ЛК' },
]

export type CreateCabinetResult =
  | { ok: true; alreadyExists: boolean }
  | { ok: false; message: string }

export interface UseClientOfdResult {
  creating: Ref<boolean>
  cabinetExists: Ref<boolean>
  cabinetStatus: Ref<string>
  password: Ref<string>
  steps: ComputedRef<OfdStep[]>
  errorMessage: ComputedRef<string>
  canRetry: ComputedRef<boolean>
  startPolling: (innGetter: () => string | undefined) => void
  stopPolling: () => void
  createCabinet: (inn: string) => Promise<CreateCabinetResult>
  applyInitialStatus: (status: string | undefined, password: string | undefined, innGetter: () => string | undefined) => void
}

export function useClientOfd(): UseClientOfdResult {
  const creating = ref<boolean>(false)
  const cabinetExists = ref<boolean>(false)
  const cabinetStatus = ref<string>('')
  const password = ref<string>('')
  let pollTimer: ReturnType<typeof setInterval> | null = null

  const steps = computed<OfdStep[]>(() => {
    const status = cabinetStatus.value
    if (!status) return []
    const isConfirmed = status === 'confirmed' || status === 'exists'
    let activeKey = ''
    let errorKey = ''
    if (status.startsWith('step:')) activeKey = status.slice(5)
    if (status.startsWith('error:')) errorKey = status.split(':')[1]

    const activeIdx = OFD_STEP_DEFS.findIndex((s) => s.key === activeKey)
    const errorIdx = OFD_STEP_DEFS.findIndex((s) => s.key === errorKey)

    return OFD_STEP_DEFS.map((s, i) => {
      let state: OfdStep['state'] = 'pending'
      if (isConfirmed) {
        state = 'done'
      } else if (errorIdx >= 0) {
        if (i < errorIdx) state = 'done'
        else if (i === errorIdx) state = 'error'
      } else if (activeIdx >= 0) {
        if (i < activeIdx) state = 'done'
        else if (i === activeIdx) state = 'active'
      }
      return { ...s, state }
    })
  })

  const errorMessage = computed<string>(() => {
    const status = cabinetStatus.value
    if (!status.startsWith('error:')) return ''
    const parts = status.split(':')
    return parts.slice(2).join(':') || 'Неизвестная ошибка'
  })

  const canRetry = computed<boolean>(() => {
    const s = cabinetStatus.value
    return s.startsWith('error:') || (s.startsWith('step:') && !pollTimer)
  })

  function stopPolling(): void {
    if (pollTimer) {
      clearInterval(pollTimer)
      pollTimer = null
    }
  }

  function startPolling(innGetter: () => string | undefined): void {
    stopPolling()
    pollTimer = setInterval(async () => {
      const inn = innGetter()
      if (!inn) return
      try {
        const { data, error } = await getOfdCabinetStatusByInn({ path: { inn } })
        if (error) return
        const d = data as { status?: string; ofd_password?: string } | undefined
        if (d?.status) cabinetStatus.value = d.status
        if (d?.ofd_password) password.value = d.ofd_password
        const s = d?.status
        if (s === 'confirmed' || s === 'exists' || s?.startsWith('error:')) {
          stopPolling()
          if (s === 'confirmed' || s === 'exists') cabinetExists.value = true
        }
      } catch {
        // 404/network — следующий tick попробует снова
      }
    }, 3000)
  }

  async function createCabinet(inn: string): Promise<CreateCabinetResult> {
    if (!inn) return { ok: false, message: 'ИНН не задан' }
    creating.value = true
    cabinetStatus.value = 'step:mailbox'
    try {
      const { data, error } = await postOfdCreateCabinet({ body: { inn } })
      if (error) {
        cabinetStatus.value = 'error:ofd_api:' + ((error as Record<string, string>).error || 'Неизвестная ошибка')
        return { ok: false, message: 'Ошибка создания ЛК OFD' }
      }
      const d = data as { status: string }
      cabinetStatus.value = d.status
      if (d.status === 'exists') {
        cabinetExists.value = true
        return { ok: true, alreadyExists: true }
      }
      return { ok: true, alreadyExists: false }
    } finally {
      creating.value = false
    }
  }

  function applyInitialStatus(status: string | undefined, pwd: string | undefined, innGetter: () => string | undefined): void {
    if (status) {
      cabinetStatus.value = status
      if (status === 'exists' || status === 'confirmed') {
        cabinetExists.value = true
      } else if (status.startsWith('step:')) {
        startPolling(innGetter)
      }
    }
    if (pwd) password.value = pwd
  }

  return {
    creating, cabinetExists, cabinetStatus, password,
    steps, errorMessage, canRetry,
    startPolling, stopPolling, createCabinet, applyInitialStatus,
  }
}

