// List godoc
// @Summary Список клиентов
// @Tags clients
// @Produce json
// @Security BearerAuth
// @Param page query int false "Страница" default(1)
// @Param limit query int false "Лимит" default(50)
// @Param search query string false "Поиск по ИНН/названию/телефону"
// @Param stage query string false "Фильтр" Enums(all,active,in_work,problems,local)
// @Param sort_by query string false "Сортировка" Enums(name,kassa_count,urgent)
// @Param sort_order query string false "Направление" Enums(asc,desc)
// @Success 200 {object} PaginatedResponse[ClientListItem]
// @Router /clients [get]
func (h *ClientsHandler) List(w http.ResponseWriter, r *http.Request) {
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	if page < 1 {
		page = 1
	}
	limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
	if limit < 1 || limit > 250 {
		limit = 50
	}
	offset := int32((page - 1) * limit)
	lim := int32(limit)
	search := r.URL.Query().Get("search")
	stage := r.URL.Query().Get("stage")
	sortBy := r.URL.Query().Get("sort_by")
	sortOrder := r.URL.Query().Get("sort_order")

	ctx := r.Context()
	params := db.ListClientsAllParams{Limit: lim, Offset: offset}

	var rows []db.ListClientsAllRow
	var total int64
	var err error

	// Search takes priority over stage filter
	if search != "" {
		searchRows, e := database.GetQueries(r.Context()).SearchClientsAll(ctx, db.SearchClientsAllParams{
			Search: search, Limit: lim, Offset: offset,
		})
		err = e
		rows = clientRowsFromSearch(searchRows)
		if err == nil {
			total, _ = database.GetQueries(r.Context()).CountClientsSearch(ctx, search)
		}
	} else {
		switch stage {
		case "active":
			stageRows, e := database.GetQueries(r.Context()).ListClientsActive(ctx, db.ListClientsActiveParams{Limit: lim, Offset: offset})
			err = e
			rows = clientRowsFromActive(stageRows)
			if err == nil {
				total, _ = database.GetQueries(r.Context()).CountClientsActive(ctx)
			}
		case "in_work":
			processingStatusID := automation.StatusRegistrationProcessingID(ctx, getTenantID(r))
			stageRows, e := database.GetQueries(r.Context()).ListClientsInWork(ctx, db.ListClientsInWorkParams{
				StatusRegistrationProcessingID: processingStatusID,
				Limit:                          lim,
				Offset:                         offset,
			})
			err = e
			rows = clientRowsFromInWork(stageRows)
			if err == nil {
				total, _ = database.GetQueries(r.Context()).CountClientsInWork(ctx, processingStatusID)
			}
		case "problems":
			stageRows, e := database.GetQueries(r.Context()).ListClientsWithProblems(ctx, db.ListClientsWithProblemsParams{Limit: lim, Offset: offset})
			err = e
			rows = clientRowsFromProblems(stageRows)
			if err == nil {
				total, _ = database.GetQueries(r.Context()).CountClientsWithProblems(ctx)
			}
		case "local":
			stageRows, e := database.GetQueries(r.Context()).ListClientsLocal(ctx, db.ListClientsLocalParams{Limit: lim, Offset: offset})
			err = e
			rows = clientRowsFromLocal(stageRows)
			if err == nil {
				total, _ = database.GetQueries(r.Context()).CountClientsLocal(ctx)
			}
		default:
			switch sortBy + ":" + sortOrder {
			case "name:desc":
				sortRows, e := database.GetQueries(r.Context()).ListClientsAllByNameDesc(ctx, db.ListClientsAllByNameDescParams{Limit: lim, Offset: offset})
				err = e
				rows = clientRowsFromNameDesc(sortRows)
			case "kassa_count:desc":
				sortRows, e := database.GetQueries(r.Context()).ListClientsAllByKassaCountDesc(ctx, db.ListClientsAllByKassaCountDescParams{Limit: lim, Offset: offset})
				err = e
				rows = clientRowsFromKassaCountDesc(sortRows)
			case "kassa_count:asc":
				sortRows, e := database.GetQueries(r.Context()).ListClientsAllByKassaCountAsc(ctx, db.ListClientsAllByKassaCountAscParams{Limit: lim, Offset: offset})
				err = e
				rows = clientRowsFromKassaCountAsc(sortRows)
			case "urgent:desc":
				sortRows, e := database.GetQueries(r.Context()).ListClientsAllByUrgentDesc(ctx, db.ListClientsAllByUrgentDescParams{Limit: lim, Offset: offset})
				err = e
				rows = clientRowsFromUrgentDesc(sortRows)
			default:
				rows, err = database.GetQueries(r.Context()).ListClientsAll(ctx, params)
			}
			if err == nil {
				total, _ = database.GetQueries(r.Context()).CountClients(ctx)
			}
		}
	}

	if err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "failed to list clients: " + err.Error()})
		return
	}

	// Convert sqlc rows → typed response items to match swagger contract.
	items := make([]ClientListItem, len(rows))
	for i, c := range rows {
		item := ClientListItem{
			ID:               c.ID,
			Name:             c.Name.String,
			Inn:              c.Inn.String,
			Phone:            c.Phone.String,
			Industry:         c.Industry.String,
			IsLocal:          c.IsLocal,
			KassaCount:       c.KassaCount,
			KassaRegistering: c.KassaRegistering,
			KassaWarning:     c.KassaWarning,
			KassaUrgent:      c.KassaUrgent,
		}
		if c.EntityType.Valid {
			item.EntityType = string(c.EntityType.ClientEntityType)
		}
		if c.GroupID.Valid {
			gid := c.GroupID.Int64
			item.GroupID = &gid
		}
		if c.GroupName.Valid {
			gname := c.GroupName.String
			item.GroupName = &gname
		}
		items[i] = item
	}

	writeJSON(w, http.StatusOK, PaginatedResponse[ClientListItem]{
		Data:  items,
		Total: total,
		Page:  page,
		Limit: limit,
	})
}

// Create godoc
// @Summary Создать локального клиента
// @Description Создание клиента без синхронизации в amoCRM
// @Tags clients
// @Accept json
// @Produce json
// @Security BearerAuth
// @Param body body CreateClientRequest true "Данные клиента"
// @Success 201 {object} CreateClientResponse
// @Failure 400 {object} ErrorResponse
// @Router /clients [post]
func (h *ClientsHandler) Create(w http.ResponseWriter, r *http.Request) {
	var req CreateClientRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid request"})
		return
	}

	if req.Name == "" {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "name is required"})
		return
	}

	pgText := func(s string) pgtype.Text {
		if s == "" {
			return pgtype.Text{}
		}
		return pgtype.Text{String: s, Valid: true}
	}

	entityType := db.NullClientEntityType{ClientEntityType: db.ClientEntityTypeIp, Valid: true}
	switch req.EntityType {
	case "ooo":
		entityType.ClientEntityType = db.ClientEntityTypeOoo
	case "ip":
		entityType.ClientEntityType = db.ClientEntityTypeIp
	case "person":
		entityType.ClientEntityType = db.ClientEntityTypePerson
	default:
		digits := 0
		for _, c := range req.Inn {
			if c >= '0' && c <= '9' {
				digits++
			}
		}
		switch digits {
		case 10:
			entityType.ClientEntityType = db.ClientEntityTypeOoo
		case 12:
			entityType.ClientEntityType = db.ClientEntityTypeIp
		default:
			entityType.ClientEntityType = db.ClientEntityTypePerson
		}
	}

	userID := actorUserIDFromCtx(r.Context())
	var createdByUserID pgtype.Int4
	if userID > 0 {
		createdByUserID = pgtype.Int4{Int32: userID, Valid: true}
	}

	row, err := database.GetQueries(r.Context()).CreateLocalClient(r.Context(), db.CreateLocalClientParams{
		Name:            pgText(req.Name),
		Inn:             pgText(req.Inn),
		Kpp:             pgText(req.Kpp),
		Ogrn:            pgText(req.Ogrn),
		Phone:           pgText(req.Phone),
		Email:           pgText(req.Email),
		Address:         pgText(req.Address),
		Industry:        pgText(req.Industry),
		ManagementName:  pgText(req.Director),
		EntityType:      entityType,
		CreatedByUserID: createdByUserID,
	})
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "failed to create client: " + err.Error()})
		return
	}

	if h.Audit != nil {
		h.Audit.Log(r.Context(), "create", "client", row.ID, nil, row)
	}

	if req.Inn != "" && h.DadataToken != "" {
		if err := h.enrichClientByINN(r.Context(), row.ID, req.Inn); err != nil {
			log.Printf("create-client: post-create enrich failed for id=%d inn=%s: %v", row.ID, req.Inn, err)
		}
	}

	writeJSON(w, http.StatusCreated, CreateClientResponse{
		ID:       row.ID,
		Name:     pgStr(row.Name),
		Inn:      pgStr(row.Inn),
		Phone:    pgStr(row.Phone),
		Email:    pgStr(row.Email),
		Address:  pgStr(row.Address),
		Industry: pgStr(row.Industry),
	})
}

// enrichClientByINN — общий код для Enrich endpoint и пост-create обогащения.
func (h *ClientsHandler) enrichClientByINN(ctx context.Context, clientID int64, inn string) error {
	party, err := dadata.FindByINN(h.DadataToken, inn)
	if err != nil {
		return err
	}

	pgText := func(s string) pgtype.Text {
		if s == "" {
			return pgtype.Text{}
		}
		return pgtype.Text{String: s, Valid: true}
	}

	var managementName, managementPost string
	if party.Management != nil {
		managementName = party.Management.Name
		managementPost = party.Management.Post
	}
	var legalAddress string
	if party.Address != nil {
		legalAddress = party.Address.Value
	}
	var taxSystem string
	if party.Finance != nil {
		taxSystem = party.Finance.TaxSystem
	}
	var regDate pgtype.Timestamptz
	if party.State.RegistrationDate != 0 {
		regDate = pgtype.Timestamptz{Time: time.UnixMilli(party.State.RegistrationDate), Valid: true}
	}
	var stateSince pgtype.Date
	if ms := party.State.StatusSinceMillis(); ms != 0 {
		stateSince = pgtype.Date{Time: time.UnixMilli(ms), Valid: true}
	}
	var employeeCount pgtype.Int4
	if party.EmployeeCount > 0 {
		employeeCount = pgtype.Int4{Int32: int32(party.EmployeeCount), Valid: true}
	}
	var capitalValue pgtype.Int8
	if party.Capital != nil && party.Capital.Value > 0 {
		capitalValue = pgtype.Int8{Int64: party.Capital.Value, Valid: true}
	}
	okvedName := party.MainOkvedName()
	if okvedName == "" && party.Okved != "" {
		okvedName = references.OkvedNames[party.Okved]
	}

	return database.GetQueries(ctx).EnrichClient(ctx, db.EnrichClientParams{
		ID:               clientID,
		Kpp:              pgText(party.Kpp),
		Okved:            pgText(party.Okved),
		OkvedName:        pgText(okvedName),
		OpfShort:         pgText(party.Opf.Short),
		OpfFull:          pgText(party.Opf.Full),
		OrgType:          pgText(party.Type),
		ManagementName:   pgText(managementName),
		ManagementPost:   pgText(managementPost),
		LegalAddress:     pgText(legalAddress),
		StateStatus:      pgText(party.State.Status),
		RegistrationDate: regDate,
		TaxSystem:        pgText(taxSystem),
		EmployeeCount:    employeeCount,
		CapitalValue:     capitalValue,
		Okpo:             pgText(party.Okpo),
		Oktmo:            pgText(party.Oktmo),
		StateStatusSince: stateSince,
		Column19:         party.Ogrn,
		DadataName:       pgText(party.Name.ShortWithOpf),
	})
}

// UpdateFields godoc
// @Summary Partial-update полей клиента
// @Description Inline-edit на карточке клиента. Только переданные поля
// @Description обновляются. Отсутствующее поле = «не менять», пустая строка = очистить.
// @Tags clients
// @Accept json
// @Produce json
// @Security BearerAuth
// @Param id path int true "ID клиента"
// @Param body body UpdateClientFieldsRequest true "Поля для обновления"
// @Success 200 {object} MessageResponse
// @Failure 400 {object} ErrorResponse
// @Failure 500 {object} ErrorResponse
// @Router /clients/{id}/fields [patch]
func (h *ClientsHandler) UpdateFields(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid id"})
		return
	}

	var req UpdateClientFieldsRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid request"})
		return
	}

	pgTextPtr := func(p *string) pgtype.Text {
		if p == nil {
			return pgtype.Text{}
		}
		return pgtype.Text{String: *p, Valid: true}
	}
	pgBoolPtr := func(p *bool) pgtype.Bool {
		if p == nil {
			return pgtype.Bool{}
		}
		return pgtype.Bool{Bool: *p, Valid: true}
	}

	var oldPhone, oldEmail, oldOgrn, oldInn, oldSnils, oldIndustry string
	var prevClient db.Client
	var prevLoaded bool
	if h.AmoPushBack != nil || h.Audit != nil {
		if prev, prevErr := database.GetQueries(r.Context()).GetClient(r.Context(), id); prevErr == nil {
			prevClient = prev
			prevLoaded = true
			oldPhone = prev.Phone.String
			oldEmail = prev.Email.String
			oldOgrn = prev.Ogrn.String
			oldInn = prev.Inn.String
			oldSnils = prev.Snils.String
			oldIndustry = prev.Industry.String
		}
	}

	var vatModes []string
	if req.VatModes != nil {
		vatModes = *req.VatModes
	}

	if err := database.GetQueries(r.Context()).UpdateClientFields(r.Context(), db.UpdateClientFieldsParams{
		ID:           id,
		Name:         pgTextPtr(req.Name),
		Inn:          pgTextPtr(req.Inn),
		Ogrn:         pgTextPtr(req.Ogrn),
		Kpp:          pgTextPtr(req.Kpp),
		Snils:        pgTextPtr(req.Snils),
		Phone:        pgTextPtr(req.Phone),
		Phone2:       pgTextPtr(req.Phone2),
		Email:        pgTextPtr(req.Email),
		Email2:       pgTextPtr(req.Email2),
		Web:          pgTextPtr(req.Web),
		Address:      pgTextPtr(req.Address),
		Industry:     pgTextPtr(req.Industry),
		VatModes:     vatModes,
		HasExcise:    pgBoolPtr(req.HasExcise),
		IsAutonomous: pgBoolPtr(req.IsAutonomous),
	}); err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "failed to update client: " + err.Error()})
		return
	}

	if h.AmoPushBack != nil {
		fields := map[string]string{}
		oldValues := map[string]string{}
		if req.Phone != nil && *req.Phone != "" {
			fields["Телефон"] = *req.Phone
			oldValues["Телефон"] = oldPhone
		}
		if req.Email != nil && *req.Email != "" {
			fields["Email"] = *req.Email
			oldValues["Email"] = oldEmail
		}
		if req.Ogrn != nil && *req.Ogrn != "" {
			fields["ОГРН"] = *req.Ogrn
			oldValues["ОГРН"] = oldOgrn
		}
		if req.Inn != nil && *req.Inn != "" {
			fields["ИНН"] = *req.Inn
			oldValues["ИНН"] = oldInn
		}
		if req.Snils != nil && *req.Snils != "" {
			fields["СНИЛС"] = *req.Snils
			oldValues["СНИЛС"] = oldSnils
		}
		if req.Industry != nil && *req.Industry != "" {
			fields["Сфера деятельности"] = *req.Industry
			oldValues["Сфера деятельности"] = oldIndustry
		}
		if len(fields) > 0 {
			h.AmoPushBack.EnqueueClientUpdate(r.Context(), id, fields, oldValues)
		}
	}

	if prevLoaded {
		if newClient, getErr := database.GetQueries(r.Context()).GetClient(r.Context(), id); getErr == nil {
			if h.Audit != nil {
				h.Audit.Log(r.Context(), "update", "client", id, prevClient, newClient)
			}
			// F6: per-field timeline в entity_change_log (одно поле = одна
			// запись). Whitelist в audit.FieldWhitelist['client'].
			audit.LogFieldChanges(r.Context(), "client", id, prevClient, newClient, "ui")
		}
	}

	writeJSON(w, http.StatusOK, MessageResponse{Status: "updated"})
}

// Get godoc
// @Summary Карточка клиента
// @Description Полный профиль: клиент + контакты + все кассы
// @Tags clients
// @Produce json
// @Security BearerAuth
// @Param id path int true "ID клиента"
// @Success 200 {object} ClientCardResponse
// @Failure 404 {object} ErrorResponse
// @Router /clients/{id} [get]
func (h *ClientsHandler) Get(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid id"})
		return
	}

	client, err := database.GetQueries(r.Context()).GetClient(r.Context(), id)
	if err != nil {
		writeJSON(w, http.StatusNotFound, ErrorResponse{Error: "client not found"})
		return
	}

	clientPgID := pgtype.Int8{Int64: client.ID, Valid: true}

	contacts, err := database.GetQueries(r.Context()).ListContactsByClient(r.Context(), clientPgID)
	if err != nil {
		contacts = []db.ListContactsByClientRow{}
	}

	kassas, err := database.GetQueries(r.Context()).ListKassasByClient(r.Context(), clientPgID)
	if err != nil {
		kassas = []db.ListKassasByClientRow{}
	}

	sales1c, _ := database.GetQueries(r.Context()).ListOnecSalesByClient(r.Context(), clientPgID)
	revenue1c, _ := database.GetQueries(r.Context()).GetOnecClientRevenue(r.Context(), clientPgID)
	talks, _ := database.GetQueries(r.Context()).ListTalksByClient(r.Context(), clientPgID)
	calls, _ := database.GetQueries(r.Context()).ListCallsByClient(r.Context(), clientPgID)

	var ofdCabinetStatus string
	var ofdPassword string
	if client.Inn.Valid {
		email := client.Inn.String + "@profitkassa.ru"
		cab, err := database.GetQueries(r.Context()).GetOfdCabinetByINN(r.Context(), email)
		if err == nil {
			if cab.OfdCabinetStatus.Valid && cab.OfdCabinetStatus.String != "" {
				ofdCabinetStatus = cab.OfdCabinetStatus.String
			} else if cab.OfdAgreementID.Valid && cab.OfdAgreementID.String != "" {
				ofdCabinetStatus = "exists"
			}
			if cab.OfdPassword.Valid {
				ofdPassword = cab.OfdPassword.String
			}
		}
	}

	writeJSON(w, http.StatusOK, ClientCardResponse{
		Client:           client,
		Contacts:         contacts,
		Kassas:           kassas,
		Sales1c:          sales1c,
		TotalRevenue:     revenue1c,
		Talks:            talks,
		Calls:            calls,
		OfdCabinetStatus: ofdCabinetStatus,
		OfdPassword:      ofdPassword,
	})
}

// Enrich godoc
// @Summary Обогатить клиента из ЕГРЮЛ
// @Description Загружает данные о компании из DaData по ИНН клиента
// @Tags clients
// @Produce json
// @Security BearerAuth
// @Param id path int true "ID клиента"
// @Success 200 {object} EnrichClientResponse
// @Failure 400 {object} ErrorResponse
// @Failure 404 {object} ErrorResponse
// @Failure 500 {object} ErrorResponse
// @Router /clients/{id}/enrich [post]
func (h *ClientsHandler) Enrich(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid id"})
		return
	}

	client, err := database.GetQueries(r.Context()).GetClient(r.Context(), id)
	if err != nil {
		writeJSON(w, http.StatusNotFound, ErrorResponse{Error: "client not found"})
		return
	}

	if !client.Inn.Valid || client.Inn.String == "" {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "client has no INN"})
		return
	}

	if err := h.enrichClientByINN(r.Context(), id, client.Inn.String); err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "enrichment failed: " + err.Error()})
		return
	}

	enriched, err := database.GetQueries(r.Context()).GetClient(r.Context(), id)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "failed to reload client"})
		return
	}
	writeJSON(w, http.StatusOK, enriched)
}

// EnrichAll godoc
// @Summary Обогатить всех клиентов из ЕГРЮЛ
// @Tags clients
// @Produce json
// @Security BearerAuth
// @Success 200 {object} MessageResponse
// @Router /clients/enrich-all [post]
func (h *ClientsHandler) EnrichAll(w http.ResponseWriter, r *http.Request) {
	tenantID := auth.GetTenantID(r.Context())
	if tenantID == 0 {
		writeJSON(w, http.StatusForbidden, ErrorResponse{Error: "tenant context required"})
		return
	}
	if h.Pool == nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "pool is not configured"})
		return
	}

	go func() {
		ctx := context.Background()

		var clients []db.ListClientsNotEnrichedRow
		if err := database.WithTenant(ctx, h.Pool, tenantID, func(q *db.Queries) error {
			rows, err := q.ListClientsNotEnriched(ctx)
			if err != nil {
				return err
			}
			clients = rows
			return nil
		}); err != nil {
			log.Printf("EnrichAll: failed to list clients: %v", err)
			return
		}
		log.Printf("EnrichAll: %d clients to enrich", len(clients))

		enriched := 0
		errors := 0
		for i, cl := range clients {
			if !cl.Inn.Valid || cl.Inn.String == "" {
				continue
			}

			party, err := dadata.FindByINN(h.DadataToken, cl.Inn.String)
			if err != nil {
				errors++
				if errors <= 5 {
					log.Printf("EnrichAll: INN %s error: %v", cl.Inn.String, err)
				}
				time.Sleep(300 * time.Millisecond)
				continue
			}

			pgText := func(s string) pgtype.Text {
				if s == "" {
					return pgtype.Text{}
				}
				return pgtype.Text{String: s, Valid: true}
			}

			var managementName, managementPost string
			if party.Management != nil {
				managementName = party.Management.Name
				managementPost = party.Management.Post
			}
			var legalAddress string
			if party.Address != nil {
				legalAddress = party.Address.Value
			}
			var taxSystem string
			if party.Finance != nil {
				taxSystem = party.Finance.TaxSystem
			}
			var regDate pgtype.Timestamptz
			if party.State.RegistrationDate != 0 {
				t := time.UnixMilli(party.State.RegistrationDate)
				regDate = pgtype.Timestamptz{Time: t, Valid: true}
			}
			var stateSince pgtype.Date
			if ms := party.State.StatusSinceMillis(); ms != 0 {
				stateSince = pgtype.Date{Time: time.UnixMilli(ms), Valid: true}
			}
			var employeeCount pgtype.Int4
			if party.EmployeeCount > 0 {
				employeeCount = pgtype.Int4{Int32: int32(party.EmployeeCount), Valid: true}
			}
			var capitalValue pgtype.Int8
			if party.Capital != nil && party.Capital.Value > 0 {
				capitalValue = pgtype.Int8{Int64: party.Capital.Value, Valid: true}
			}
			okvedName := party.MainOkvedName()
			if okvedName == "" && party.Okved != "" {
				okvedName = references.OkvedNames[party.Okved]
			}

			if err := database.WithTenant(ctx, h.Pool, tenantID, func(q *db.Queries) error {
				return q.EnrichClient(ctx, db.EnrichClientParams{
					ID: cl.ID,
					Kpp: pgText(party.Kpp), Okved: pgText(party.Okved), OkvedName: pgText(okvedName),
					OpfShort: pgText(party.Opf.Short), OpfFull: pgText(party.Opf.Full),
					OrgType: pgText(party.Type), ManagementName: pgText(managementName),
					ManagementPost: pgText(managementPost), LegalAddress: pgText(legalAddress),
					StateStatus: pgText(party.State.Status), RegistrationDate: regDate,
					TaxSystem: pgText(taxSystem), EmployeeCount: employeeCount,
					CapitalValue: capitalValue, Okpo: pgText(party.Okpo), Oktmo: pgText(party.Oktmo),
					StateStatusSince: stateSince,
					DadataName:       pgText(party.Name.ShortWithOpf),
				})
			}); err != nil {
				errors++
				if errors <= 5 {
					log.Printf("EnrichAll: INN %s db error: %v", cl.Inn.String, err)
				}
				continue
			}
			enriched++

			if (i+1)%100 == 0 {
				log.Printf("EnrichAll: %d/%d done, %d errors", i+1, len(clients), errors)
			}
			time.Sleep(200 * time.Millisecond)
		}
		log.Printf("EnrichAll: done — %d enriched, %d errors", enriched, errors)
	}()

	writeJSON(w, http.StatusOK, MessageResponse{Status: "enrichment started"})
}

// ListClosed godoc
// @Summary Список закрытых организаций
// ClosedClientItem — облегчённое представление закрытого клиента в /clients/closed.
type ClosedClientItem struct {
	ID          int64  `json:"id" validate:"required"`
	Name        string `json:"name" validate:"required"`
	Inn         string `json:"inn" validate:"required"`
	Industry    string `json:"industry" validate:"required"`
	StateStatus string `json:"state_status" validate:"required"`
}

// ClosedClientsResponse — пагинированный ответ /clients/closed.
type ClosedClientsResponse struct {
	Data  []ClosedClientItem `json:"data" validate:"required"`
	Total int64              `json:"total" validate:"required"`
	Page  int                `json:"page" validate:"required"`
	Limit int                `json:"limit" validate:"required"`
}

// @Tags clients
// @Produce json
// @Param page query int false "Страница"
// @Param limit query int false "Лимит"
// @Security BearerAuth
// @Success 200 {object} ClosedClientsResponse
// @Router /clients/closed [get]
func (h *ClientsHandler) ListClosed(w http.ResponseWriter, r *http.Request) {
	page, _ := strconv.Atoi(r.URL.Query().Get("page"))
	if page < 1 { page = 1 }
	limit, _ := strconv.Atoi(r.URL.Query().Get("limit"))
	if limit < 1 || limit > 250 { limit = 25 }
	offset := int32((page - 1) * limit)

	rows, err := database.GetQueries(r.Context()).ListClosedClients(r.Context(), db.ListClosedClientsParams{Limit: int32(limit), Offset: offset})
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: "failed to list closed clients"})
		return
	}
	total, _ := database.GetQueries(r.Context()).CountClosedClients(r.Context())

	items := make([]ClosedClientItem, 0, len(rows))
	for _, r := range rows {
		items = append(items, ClosedClientItem{
			ID:          r.ID,
			Name:        pgStr(r.Name),
			Inn:         pgStr(r.Inn),
			Industry:    pgStr(r.Industry),
			StateStatus: pgStr(r.StateStatus),
		})
	}

	writeJSON(w, http.StatusOK, ClosedClientsResponse{Data: items, Total: total, Page: page, Limit: limit})
}

