// @Success 200 {object} ClientByINNResponse
// @Failure 404 {object} ErrorResponse
// @Router /clients/by-inn/{inn} [get]
func (h *ClientsHandler) GetByINN(w http.ResponseWriter, r *http.Request) {
	inn := chi.URLParam(r, "inn")
	if inn == "" {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "inn is required"})
		return
	}

	cl, err := database.GetQueries(r.Context()).GetClientByINN(r.Context(), pgtype.Text{String: inn, Valid: true})
	if err != nil {
		writeJSON(w, http.StatusNotFound, ErrorResponse{Error: "client not found"})
		return
	}

	writeJSON(w, http.StatusOK, ClientByINNResponse{
		ID:   cl.ID,
		Name: pgStr(cl.Name),
		Inn:  pgStr(cl.Inn),
	})
}

// ClientHandedKassa — одна запись «касса передана клиенту» для таймлайна клиента.
type ClientHandedKassa struct {
	KassaID          int64  `json:"kassa_id" validate:"required"`
	KassaModel       string `json:"kassa_model" validate:"required"`
	KassaZn          string `json:"kassa_zn" validate:"required"`
	HandedToClientAt string `json:"handed_to_client_at" validate:"required" example:"2026-04-20"`
	UpdatedAt        string `json:"updated_at" validate:"required"`
}

// HandedKassas godoc
// @Summary Список касс клиента, переданных клиенту
// @Description Для таймлайна клиента — показываем когда и какие кассы переданы.
// @Tags clients
// @Accept json
// @Produce json
// @Security BearerAuth
// @Param id path int true "Client ID"
// @Success 200 {array} ClientHandedKassa
// @Failure 401 {object} ErrorResponse
// @Router /clients/{id}/handed-kassas [get]
func (h *ClientsHandler) HandedKassas(w http.ResponseWriter, r *http.Request) {
	id, err := strconv.ParseInt(chi.URLParam(r, "id"), 10, 64)
	if err != nil {
		writeJSON(w, http.StatusBadRequest, ErrorResponse{Error: "invalid id"})
		return
	}

	rows, err := database.GetQueries(r.Context()).ListHandedKassasByClient(
		r.Context(),
		pgtype.Int8{Int64: id, Valid: true},
	)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, ErrorResponse{Error: err.Error()})
		return
	}

	resp := make([]ClientHandedKassa, 0, len(rows))
	for _, row := range rows {
		item := ClientHandedKassa{
			KassaID:    row.KassaID,
			KassaModel: row.KassaModel,
			KassaZn:    row.KassaZn,
		}
		if row.HandedToClientAt.Valid {
			item.HandedToClientAt = row.HandedToClientAt.Time.Format("2006-01-02")
		}
		if row.UpdatedAt.Valid {
			item.UpdatedAt = row.UpdatedAt.Time.Format(time.RFC3339)
		}
		resp = append(resp, item)
	}

	writeJSON(w, http.StatusOK, resp)
}

