package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"bizprofit/internal/config"
	"bizprofit/internal/database"
	db "bizprofit/internal/database/db"
	"bizprofit/internal/handlers"
	"bizprofit/internal/scheduler"
	"bizprofit/internal/scheduler/jobs"

	"github.com/go-chi/chi/v5"
	chimw "github.com/go-chi/chi/v5/middleware"
	"github.com/go-chi/cors"
)

// @title BizProfit API
// @version 1.0
// @description API для системы управления кассовой техникой ПрофитКасса
// @host localhost:8080
// @BasePath /api
// @securityDefinitions.apikey BearerAuth
// @in header
// @name Authorization
// @description Введите JWT токен в формате: Bearer {token}
func main() {
	cfg, err := config.Load()
	if err != nil {
		log.Fatalf("Failed to load config: %v", err)
	}

	ctx := context.Background()

	pool, err := database.Connect(ctx, cfg.DatabaseURL)
	if err != nil {
		log.Fatalf("Failed to connect to database: %v", err)
	}
	defer pool.Close()

	if err := database.Migrate(ctx, pool); err != nil {
		log.Fatalf("Failed to run migrations: %v", err)
	}

	queries := db.New(pool)

	// Seed admin + выездных техников. Idempotent.
	if err := handlers.SeedAdmin(ctx, queries, cfg.AdminLogin, cfg.AdminPassword); err != nil {
		log.Printf("Warning: failed to seed admin: %v", err)
	}
	if err := handlers.SeedFieldTechs(ctx, queries); err != nil {
		log.Printf("Warning: failed to seed field_tech users: %v", err)
	}

	// Внешние клиенты + cross-cutting сервисы — см. deps.go.
	deps, err := BuildDeps(ctx, cfg, pool, queries)
	if err != nil {
		log.Fatalf("Failed to build deps: %v", err)
	}

	// Default tenant — до перехода на multi-tenant scheduler.
	const defaultTenantID int32 = 1
	deps.ApplyDefaultTenant(defaultTenantID)

	// Cron scheduler — нуждается в syncer'ах с проставленным TenantID.
	cronScheduler := scheduler.StartCron(jobs.Deps{
		Pool:                  pool,
		Queries:               queries,
		AmoSyncer:             deps.AmoSyncer,
		OfdSyncer:             deps.OfdSyncer,
		OnecSyncer:            deps.OnecSyncer,
		WazzupSender:          deps.WazzupSender,
		MoizvonkiSyncer:       deps.MoizvonkiSyncer,
		AmoPushBack:           deps.AmoPushBackService,
		DefaultTenantID:       defaultTenantID,
		AutomationSendEnabled: cfg.AutomationSendEnabled,
		DadataToken:           cfg.DadataToken,
	})
	if !cfg.AutomationSendEnabled {
		log.Println("AUTOMATION_SEND_ENABLED=false — date-triggers НЕ будут отправлять сообщения клиентам. Триггеры продолжат создавать fallback-задачи в канбане.")
	}
	defer cronScheduler.Stop()

	// HTTP handlers — собирает все handler-structs из deps + queries + pool.
	h := BuildAppHandlers(deps, queries, pool, cfg)

	// Router
	r := chi.NewRouter()
	r.Use(chimw.Logger)
	r.Use(chimw.Recoverer)
	r.Use(chimw.RealIP)
	r.Use(cors.Handler(cors.Options{
		AllowedOrigins:   []string{"*"},
		AllowedMethods:   []string{"GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"},
		AllowedHeaders:   []string{"Accept", "Authorization", "Content-Type"},
		ExposedHeaders:   []string{"Content-Disposition"},
		AllowCredentials: true,
		MaxAge:           300,
	}))

	registerRoutes(r, cfg, h, queries, pool)

	srv := &http.Server{
		Addr:         ":" + cfg.Port,
		Handler:      r,
		ReadTimeout:  15 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  60 * time.Second,
	}

	// Reset stuck sync logs from previous runs.
	queries.ResetStuckSyncLogs(context.Background())

	// Graceful shutdown.
	go func() {
		log.Printf("Server starting on :%s", cfg.Port)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("Server failed: %v", err)
		}
	}()

	// Register Wazzup webhook after server is up.
	if deps.WazzupClient != nil && cfg.WazzupWebhookURL != "" {
		go func() {
			time.Sleep(2 * time.Second)
			if err := deps.WazzupClient.RegisterWebhook(cfg.WazzupWebhookURL); err != nil {
				log.Printf("Warning: failed to register Wazzup webhook: %v", err)
			} else {
				log.Println("Wazzup webhook registered")
			}
		}()
	}

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit
	log.Println("Shutting down server...")

	shutdownCtx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	if err := srv.Shutdown(shutdownCtx); err != nil {
		log.Fatalf("Server forced to shutdown: %v", err)
	}

	log.Println("Server stopped")
}

