import { ref, computed, type Ref, type ComputedRef } from 'vue'
import { postKassasByIdTransition } from '@/api/generated'
import type { KassaDetail, ChecklistData } from './useKassaDetail'

// Lifecycle-домен KassaDetailPage: transitions между sale→processing→active→
// renewal→repair→deregistered/rejected.
// canRepair/canReject — guards для UI кнопок.
// completionHints — bullet-list чего не хватает чтобы закрыть processing.

export type LifecycleStatus =
  'sale' | 'processing' | 'active' | 'renewal' | 'repair' |
  'deregistered' | 'rejected' | 'fn_expired' |
  // '_return' — deprecated control-flow токен. Backend всё ещё принимает
  // его для обратной совместимости, но новый код использует флаг
  // ReturnPrevious=true в TransitionRequest body. transition() ниже
  // транслирует '_return' → return_previous: true автоматически.
  '_return'

export const LIFECYCLE_LABELS: Record<string, string> = {
  sale:         'Продажа',
  processing:   'В работе',
  active:       'Активна',
  fn_expired:   'ФН истёк',
  renewal:      'Продление',
  repair:       'В ремонте',
  deregistered: 'Снята с учёта',
  rejected:     'Закрыто и не реализовано',
}

export const LIFECYCLE_COLORS: Record<string, string> = {
  sale:         'deep-purple',
  processing:   'amber',
  active:       'green',
  fn_expired:   'red-darken-4',
  renewal:      'blue',
  repair:       'blue-grey',
  deregistered: 'grey',
  rejected:     'red-lighten-1',
}

export const LIFECYCLE_ICONS: Record<string, string> = {
  sale:         'mdi-cart-outline',
  processing:   'mdi-file-document-edit-outline',
  active:       'mdi-check-circle',
  fn_expired:   'mdi-clock-alert',
  renewal:      'mdi-autorenew',
  repair:       'mdi-wrench',
  deregistered: 'mdi-close-circle',
  rejected:     'mdi-cancel',
}

export interface UseKassaLifecycleArgs {
  kassa: Ref<KassaDetail | null>
  checklist: Ref<ChecklistData | null>
  reload: (kassaId: number) => Promise<void>
}

export interface UseKassaLifecycleResult {
  lifecycleLabel: ComputedRef<string>
  lifecycleColor: ComputedRef<string>
  lifecycleIcon: ComputedRef<string>
  canRepair: ComputedRef<boolean>
  canReject: ComputedRef<boolean>
  canCompleteProcessing: ComputedRef<boolean>
  completionHints: ComputedRef<string[]>
  showRejectDialog: Ref<boolean>
  rejectReason: Ref<string>
  rejectReasonCustom: Ref<string>
  confirmReject: () => Promise<void>
  transition: (status: LifecycleStatus, rejectionReasonStr?: string) => Promise<void>
}

export function useKassaLifecycle(args: UseKassaLifecycleArgs): UseKassaLifecycleResult {
  const lifecycleLabel = computed<string>(() =>
    LIFECYCLE_LABELS[args.kassa.value?.lifecycle_status || ''] || '—',
  )

  const lifecycleColor = computed<string>(() => {
    const status = args.kassa.value?.lifecycle_status || ''
    if (status === 'active' && args.kassa.value?.fn_deadline) {
      const days = (new Date(args.kassa.value.fn_deadline).getTime() - Date.now()) / 86400000
      if (days <= 0) return 'red-darken-4'
      if (days <= 7) return 'red'
      if (days <= 30) return 'orange'
    }
    return LIFECYCLE_COLORS[status] || 'grey'
  })

  const lifecycleIcon = computed<string>(() =>
    LIFECYCLE_ICONS[args.kassa.value?.lifecycle_status || ''] || 'mdi-circle',
  )

  const canRepair = computed<boolean>(() => {
    const s = args.kassa.value?.lifecycle_status
    return s === 'processing' || s === 'active' || s === 'renewal' || s === 'repair'
  })

  const canReject = computed<boolean>(() => {
    const s = args.kassa.value?.lifecycle_status
    return !!s && !['deregistered', 'rejected'].includes(s)
  })

  // canCompleteProcessing: fns_status==registered + handed_to_client_at + sms_sent +
  // open_tasks_count==0. completionHints — что осталось закрыть.
  const canCompleteProcessing = computed<boolean>(() => {
    const cl = args.checklist.value
    if (!cl) return false
    if (cl.fns_status !== 'registered') return false
    if (!cl.handed_to_client_at) return false
    if (!cl.sms_sent) return false
    if ((cl.open_tasks_count ?? 0) > 0) return false
    return true
  })

  const completionHints = computed<string[]>(() => {
    const cl = args.checklist.value
    if (!cl) return []
    const hints: string[] = []
    if (cl.fns_status !== 'registered') hints.push('регистрация в ФНС')
    if (!cl.handed_to_client_at) hints.push('передача клиенту')
    if (!cl.sms_sent) hints.push('отправка уведомления о готовности')
    if ((cl.open_tasks_count ?? 0) > 0) hints.push(`закрытие открытых задач (${cl.open_tasks_count})`)
    return hints
  })

  const showRejectDialog = ref<boolean>(false)
  const rejectReason = ref<string>('Клиент передумал')
  const rejectReasonCustom = ref<string>('')

  async function transition(
    status: LifecycleStatus,
    rejectionReasonStr?: string,
  ): Promise<void> {
    if (!args.kassa.value) return
    const id = args.kassa.value.id as number
    // _return → return_previous: true
    // fn_expired — derived status → переводим в renewal
    type BodyStatus = 'sale' | 'processing' | 'active' | 'renewal' | 'repair' | 'deregistered' | 'rejected'
    const returnPrevious = status === '_return'
    let bodyStatus: BodyStatus | undefined
    if (returnPrevious) bodyStatus = undefined
    else if (status === 'fn_expired') bodyStatus = 'renewal'
    else bodyStatus = status

    const body: {
      status?: BodyStatus
      rejection_reason?: string
      return_previous?: boolean
    } = {
      rejection_reason: rejectionReasonStr,
    }
    if (bodyStatus) body.status = bodyStatus
    if (returnPrevious) body.return_previous = true

    const { data } = await postKassasByIdTransition({
      path: { id },
      body,
    })
    if (data) await args.reload(id)
  }

  async function confirmReject(): Promise<void> {
    const reason = rejectReason.value === 'other' ? rejectReasonCustom.value : rejectReason.value
    await transition('rejected', reason)
    showRejectDialog.value = false
  }

  return {
    lifecycleLabel, lifecycleColor, lifecycleIcon,
    canRepair, canReject,
    canCompleteProcessing, completionHints,
    showRejectDialog, rejectReason, rejectReasonCustom,
    confirmReject, transition,
  }
}

