/**
 * downloadBlob — общий helper: получить Blob от любого hey-api endpoint и
 * предложить пользователю сохранить файл. Имя берётся из Content-Disposition
 * либо из fallback. Hey-api parseAs:'blob' возвращает Blob через data, и
 * Response объект через response — оттуда читаем заголовок Content-Disposition.
 */
export interface DownloadResult {
  data?: Blob
  response?: Response
}

export function saveBlobAs(result: DownloadResult, fallbackName: string): void {
  if (!result.data) {
    throw new Error('Empty response body')
  }
  const disposition = result.response?.headers.get('Content-Disposition') ?? null
  let filename = fallbackName

  if (disposition) {
    const utf8Match = disposition.match(/filename\*=UTF-8''(.+)/i)
    if (utf8Match) {
      filename = decodeURIComponent(utf8Match[1])
    } else {
      const match = disposition.match(/filename="?([^"]+)"?/i)
      if (match) filename = match[1]
    }
  }

  const a = document.createElement('a')
  a.href = URL.createObjectURL(result.data)
  a.download = filename
  a.click()
  URL.revokeObjectURL(a.href)
}

