//! Output buffer pool for hot decoder kernels.
//!
//! Pre-allocates and re-uses `Tensor`s across forward passes so the GEMV
//! / paged-attention / norm hot path stops calling `cuMemAlloc` on every
//! op.  cuMemAlloc on a 8 GB Ada laptop costs ~3-6 µs per call; with the
//! AWQ INT4 GEMV alone landing 252 calls per token (7 linears × 36 layers),
//! eliminating the syscall round-trip is worth ~1-2 ms per token at
//! steady state — and is the single biggest blocker for CUDA Graph
//! capture once we own the stream lifecycle (Stage 11).
//!
//! ## Usage contract
//!
//! 1. `OutputPool::reset_cursors()` is called once at the start of every
//!    decode forward in [`crate::engine::helpers::execute_batched_decode_with_graph`].
//!    This rewinds all per-shape round-robin cursors back to zero.
//! 2. Each kernel-launch site that wants a pre-allocated output requests
//!    one via one of two entry points:
//!
//!      - [`OutputPool::reserve_pooled`] — generic, returns a
//!        [`PooledTensor`] for any `(shape, dtype)`.
//!      - One of the four tagged reserves
//!        ([`OutputPool::reserve_positions`], [`OutputPool::reserve_slot_mapping`],
//!        [`OutputPool::reserve_block_tables`], [`OutputPool::reserve_seq_lens`])
//!        for decode-batch metadata buffers. Each tag has its own
//!        [`SlotKind`] bucket and cursor namespace, so unrelated tagged
//!        reserves and the generic pool cannot drift into shared slots.
//!
//!    The first call for a given key allocates a fresh tensor;
//!    subsequent calls within the same forward step return *distinct*
//!    pre-allocated tensors at increasing pool indices, and grow the
//!    pool on demand if the pool runs out of pre-allocated buffers.
//! 3. The returned tensor shares storage (Arc-cloned) with the pooled
//!    tensor — kernels write into that storage; the caller hands the
//!    tensor down the layer chain; the storage stays alive for the life
//!    of the pool. Wrappers that need a bare `Tensor` should call
//!    `.into_tensor()` at the pool boundary so the type-erasure is
//!    locally visible in code review.
//!
//! Because forwards are executed serially inside the engine task, a
//! single global pool is safe.  A `Mutex` guards the inner map; the
//! critical section is a HashMap lookup + index, dwarfed by the µs-scale
//! kernel launches it amortises.
//!
//! When invoked from non-pooled paths (eager prefill, tests), kernels
//! continue allocating their own buffers — the pool is opt-in per call
//! site, not a global override.

use std::cell::Cell;
use std::collections::HashMap;
use std::marker::PhantomData;
use std::sync::{Mutex, OnceLock};

use candle_core::{DType, Device, Result, Shape, Tensor};

// ─── Execution-mode gate ────────────────────────────────────────────
//
// Pool reservations have one of two semantics:
//
// * **Decode mode** (default): every `reserve` / `reserve_pooled` call
//   goes through the per-shape bucket so device pointers stay stable
//   across forward passes. This invariant is essential for captured
//   CUDA Graph replay — a captured kernel records its tensor pointers
//   once and reads from those same addresses on every subsequent
//   replay.
//
// * **Prefill mode**: prefill is eager (never captured) and per-prompt
//   `M` (= num_batched_tokens) is unique on every request, so a
//   pool-retained `[M, hidden]` allocation would wedge for the engine
//   lifetime. Large reservations under this mode bypass the pool —
//   `Tensor::zeros` directly, drop on scope end.
//
// The mode is thread-local: today the engine task runs forward
// sequentially on one thread per request, so a `ModeGuard` set at the
// `execute_prefill` entry point covers every `reserve` site reached
// through that forward. If a future parallel-forward refactor needs
// to share guards across threads, switch to an `Atomic` or an explicit
// argument through `ForwardContext`.

/// Two semantics under which pool reservations operate. See module
/// comment for the full rationale.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub enum ExecutionMode {
    /// Captured-graph-friendly: every reserve pools-back so device
    /// pointers stay stable across forwards. The default mode.
    #[default]
    Decode,
    /// Eager prefill / warmup: reservations ≥ [`LARGE_PREFILL_BYTES`]
    /// bypass the pool and drop on scope exit; smaller reservations
    /// still pool-back so a later captured decode replays cleanly.
    Prefill,
}

thread_local! {
    static CURRENT_MODE: Cell<ExecutionMode> =
        const { Cell::new(ExecutionMode::Decode) };
}

impl ExecutionMode {
    /// Snapshot of the current thread's execution mode.
    #[inline]
    pub fn current() -> Self {
        CURRENT_MODE.with(|c| c.get())
    }
}

/// RAII guard: sets the thread-local execution mode for its lifetime
/// and restores the previous mode on `Drop`. Re-entrant — nested
/// guards correctly restore their immediate predecessor.
#[must_use = "ModeGuard restores the previous mode on Drop; binding it as \
              `_` would restore immediately and defeat the gate"]
pub struct ModeGuard {
    prev: ExecutionMode,
}

impl ModeGuard {
    /// Enter [`ExecutionMode::Prefill`] for the lifetime of the guard.
    pub fn prefill() -> Self {
        Self::set(ExecutionMode::Prefill)
    }
    /// Enter (or re-affirm) [`ExecutionMode::Decode`] for the lifetime
    /// of the guard. Useful as a defensive barrier at decode entry
    /// points so a stale `Prefill` mode leaked from a prior forward
    /// can never bleed into a captured replay.
    pub fn decode() -> Self {
        Self::set(ExecutionMode::Decode)
    }
    fn set(new: ExecutionMode) -> Self {
        let prev = CURRENT_MODE.with(|c| c.replace(new));
        Self { prev }
    }
}

impl Drop for ModeGuard {
    fn drop(&mut self) {
        CURRENT_MODE.with(|c| c.set(self.prev));
    }
}

// ─── Capture-region tripwire ────────────────────────────────────────
//
// Set by `CudaGraphRunner` for the lifetime of `BeginCapture` →
// `EndCapture`. The Prefill-bypass branch in `reserve` /
// `reserve_kind` `debug_assert!`s that this flag is OFF — capturing
// a kernel that reads a non-pool-backed `Tensor::zeros` pointer would
// silently violate replay-stability. ModeGuard::prefill is the public
// gate that ensures it; this tripwire catches accidental gate
// violations in debug builds at near-zero release cost (asserts go
// away entirely with `-O`).

thread_local! {
    static IS_CAPTURING: Cell<bool> = const { Cell::new(false) };
}

/// Mark the current thread as inside a CUDA Graph capture region.
/// Pair with [`set_capturing(false)`] at `EndCapture`. RAII helper
/// [`CaptureScope`] is preferred to guarantee balanced flip.
pub fn set_capturing(on: bool) {
    IS_CAPTURING.with(|c| c.set(on));
}

/// True iff the current thread is inside a `BeginCapture`/`EndCapture`
/// region. Used by the pool's bypass-path `debug_assert!`.
pub fn is_capturing() -> bool {
    IS_CAPTURING.with(|c| c.get())
}

/// RAII helper that flips [`is_capturing`] to `true` for its lifetime
/// and restores the previous value on `Drop`. Preferred over raw
/// [`set_capturing`] calls so an early `?` / panic inside the capture
/// region can't leave the flag dangling.
#[must_use = "CaptureScope clears the flag on Drop; binding as _ would clear immediately"]
pub struct CaptureScope {
    prev: bool,
}

impl CaptureScope {
    pub fn enter() -> Self {
        let prev = IS_CAPTURING.with(|c| c.replace(true));
        Self { prev }
    }
}

impl Drop for CaptureScope {
    fn drop(&mut self) {
        IS_CAPTURING.with(|c| c.set(self.prev));
    }
}

/// Default auto-bypass threshold for Prefill mode. Reservations whose
/// tensor byte size meets or exceeds this value are diverted to a
/// fresh `Tensor::zeros` (not retained in the pool).
///
/// Calibrated on Qwen3-8B (vocab=151k) at RTX 4060 8 GB:
/// - decode-mode worst case reaches `[batch≤32, vocab] F16 ≈ 9.6 MiB`
///   when captures are sized for the largest registered batch, but in
///   practice the default capture-batch routing lands much smaller
///   (`[1, vocab] F16 = 296 KiB`).
/// - prefill workspaces cross 8 MiB on any per-layer `[M, hidden]`
///   buffer once `M ≳ 1000` (e.g. lm_head at `M=1179` is 358 MiB).
///
/// 8 MiB sits comfortably above the small decode-mode reserves we want
/// to pool and well below any meaningful prefill workspace we want to
/// bypass. Override at process start via `VLLM_RUST_PREFILL_BYPASS_BYTES`
/// (accepts a raw byte count or `K`/`M`/`G` suffix, e.g. `16M`).
pub const DEFAULT_LARGE_PREFILL_BYTES: usize = 8 * 1024 * 1024;

/// Returns the effective bypass threshold. Reads
/// `VLLM_RUST_PREFILL_BYPASS_BYTES` on first call and caches it for
/// the lifetime of the process so the hot path stays env-call-free.
fn large_prefill_bytes() -> usize {
    static CACHE: OnceLock<usize> = OnceLock::new();
    *CACHE.get_or_init(|| {
        std::env::var("VLLM_RUST_PREFILL_BYPASS_BYTES")
            .ok()
            .as_deref()
            .and_then(parse_byte_size)
            .unwrap_or(DEFAULT_LARGE_PREFILL_BYTES)
    })
}

/// Parse a human-friendly byte-size string. Accepted forms:
///   - bare integer: `"8388608"` → 8 388 608
///   - integer + `B` / `K` / `M` / `G` (case-insensitive), with
///     optional `iB` suffix that's ignored: `"16M"` / `"16Mi"` /
///     `"16MiB"` → 16 * 1024 * 1024
///
/// Returns `None` on any parse failure or overflow — the caller falls
/// back to [`DEFAULT_LARGE_PREFILL_BYTES`] so a malformed env var
/// never disables the bypass silently.
fn parse_byte_size(s: &str) -> Option<usize> {
    let s = s.trim();
    if s.is_empty() {
        return None;
    }
    let lower = s.to_ascii_lowercase();
    // Strip an optional binary-suffix tail (`iB`, `B`) so both "16M"
    // and "16MiB" parse the same way.
    let core: &str = if let Some(stripped) = lower.strip_suffix("ib") {
        stripped
    } else if let Some(stripped) = lower.strip_suffix('b') {
        stripped
    } else {
        &lower
    };
    let (digits, mul): (&str, usize) = match core.as_bytes().last().copied() {
        Some(b'k') => (&core[..core.len() - 1], 1024),
        Some(b'm') => (&core[..core.len() - 1], 1024 * 1024),
        Some(b'g') => (&core[..core.len() - 1], 1024 * 1024 * 1024),
        Some(c) if c.is_ascii_digit() => (core, 1),
        _ => return None,
    };
    digits.trim().parse::<usize>().ok()?.checked_mul(mul)
}

#[inline]
fn should_bypass_pool(shape: &[usize], dtype: DType) -> bool {
    if ExecutionMode::current() != ExecutionMode::Prefill {
        return false;
    }
    let elems: usize = shape.iter().product();
    elems.saturating_mul(dtype.size_in_bytes()) >= large_prefill_bytes()
}

// ─── Slot kinds ─────────────────────────────────────────────────────
//
// Generic pool entries share one round-robin cursor per `(dtype, shape)`.
// The four tagged kinds below give the critical decode-batch buffers
// (positions, slot_mapping, block_tables, seq_lens) their own
// independent cursors, eliminating the slot-drift failure mode where a
// generic `reserve_pooled([1], U32, …)` collides with a `positions`
// reserve at the same shape and the cursors end up advancing in
// unexpected interleavings (Bug B.1, commit 2614dd7).
#[derive(Clone, Copy, Hash, PartialEq, Eq, Debug)]
enum SlotKind {
    Generic,
    Positions,
    SlotMapping,
    BlockTables,
    SeqLens,
}

/// Tag marker for the per-token query-position buffer.
#[derive(Debug)]
pub struct Positions;
/// Tag marker for the per-token KV-cache slot index buffer.
#[derive(Debug)]
pub struct SlotMapping;
/// Tag marker for the `[batch, max_blocks_per_seq]` block-id table.
#[derive(Debug)]
pub struct BlockTables;
/// Tag marker for the `[batch]` per-sequence length vector.
#[derive(Debug)]
pub struct SeqLens;

/// Phantom-typed handle for a pool slot of a specific decode-batch
/// role. Constructible only via [`OutputPool::reserve_positions`] et al,
/// so a `TaggedSlot<Positions>` cannot be confused with a generic
/// [`PooledTensor`] at compile time. The wrapped storage is still
/// pool-backed (it IS a [`PooledTensor`] internally), so all
/// view-method and as-tensor access is preserved.
#[derive(Debug)]
pub struct TaggedSlot<Tag> {
    inner: PooledTensor,
    _phantom: PhantomData<fn() -> Tag>,
}

// Manual `Clone` — `#[derive]` would unnecessarily require `Tag: Clone`
// even though the `fn() -> Tag` phantom is `Clone` for any `Tag`.
impl<Tag> Clone for TaggedSlot<Tag> {
    fn clone(&self) -> Self {
        Self {
            inner: self.inner.clone(),
            _phantom: PhantomData,
        }
    }
}

impl<Tag> TaggedSlot<Tag> {
    fn new(inner: PooledTensor) -> Self {
        Self {
            inner,
            _phantom: PhantomData,
        }
    }

    /// Tag an already-`PooledTensor` view as this tag without going
    /// through the pool's `reserve_*` cursor. Internal use only:
    /// `build_decode_batch_shared_with_options` calls this in the
    /// non-CUDA / oversize-batch fallback branch, where the storage
    /// is a `from_pool_unchecked`-wrapped one-shot `Tensor::from_vec`
    /// that lives for the caller's forward but is not pool-managed.
    /// Eager-only paths never feed it into a captured graph, so the
    /// "pool-backed = address-stable" contract isn't required there.
    #[doc(hidden)]
    pub fn __from_pool_unchecked(inner: PooledTensor) -> Self {
        Self {
            inner,
            _phantom: PhantomData,
        }
    }

    /// Read-only access to the underlying tensor — the same backing
    /// device storage the pool retains.
    pub fn as_tensor(&self) -> &Tensor {
        self.inner.as_tensor()
    }

    /// Borrow the pool-backed view as a [`PooledTensor`]. Useful when
    /// passing to APIs that already accept `&PooledTensor`.
    pub fn as_pooled(&self) -> &PooledTensor {
        &self.inner
    }

    pub fn dims(&self) -> &[usize] {
        self.inner.dims()
    }

    pub fn dtype(&self) -> DType {
        self.inner.dtype()
    }

    pub fn shape(&self) -> &Shape {
        self.inner.shape()
    }
}

/// Type-level guarantee that a [`Tensor`]'s underlying device storage was
/// reserved from an [`OutputPool`] (or another `'static`-equivalent
/// source explicitly opted into by `from_pool_unchecked`). The pool's
/// buffers are never freed for the lifetime of the pool — `OutputPool::global()`
/// is `'static`, so a captured CUDA-Graph kernel may safely encode the
/// device pointer of any `PooledTensor`'s storage into a recorded kernel
/// node; replay reads from the same address forever.
///
/// Construction:
/// - [`OutputPool::reserve_pooled`] is the primary safe constructor.
/// - View-like methods on an existing `PooledTensor` (`reshape`, `narrow`,
///   `unsqueeze`, `squeeze`, `transpose`, `flatten_all`) preserve the
///   storage and therefore preserve the invariant.
/// - [`PooledTensor::from_pool_unchecked`] is the unsafe escape hatch
///   used internally when the source is a non-pool but `'static` storage
///   (e.g., the captured-graph input-ids buffer owned by `CudaGraphRunner`
///   for the lifetime of the runner). External callers should not need it.
///
/// Read-only conversion back to `&Tensor` via [`PooledTensor::as_tensor`]
/// is freely available; it does not violate the invariant because views
/// share storage. Owning `Tensor` ([`PooledTensor::into_tensor`]) returns
/// the underlying Arc-shared `Tensor` — the storage is still pool-backed,
/// the caller just loses the type-level guarantee.
#[derive(Clone, Debug)]
#[repr(transparent)]
pub struct PooledTensor {
    inner: Tensor,
}

