        let trellis = Tensor::zeros((1, 1, 64), DType::I16, &Device::Cpu).unwrap();
        let suh = Tensor::zeros(16, DType::F16, &Device::Cpu).unwrap();
        let svh = Tensor::zeros(16, DType::F16, &Device::Cpu).unwrap();
        let lin = Exl3Linear {
            trellis,
            suh,
            svh,
            mcg: false,
            mul1: false,
