package service

import (
	"context"
	"errors"
	"fmt"
	"io"
	"math"
	"strings"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"
	"github.com/xuri/excelize/v2"

	db "v-calc/internal/db/sqlc"
	"v-calc/internal/service/shared/xlsximport"
	"v-calc/internal/shared"
)

// floatEqual — сравнение с epsilon, чтобы floating-point округления не
// приводили к ложным UPDATE-ам после сериализации в numeric и обратно.
const floatEpsilon = 1e-6

func floatEqual(a, b float64) bool { return math.Abs(a-b) < floatEpsilon }

func numericToFloat(n pgtype.Numeric) float64 { return shared.FromNumeric(n) }

// runInSavepoint выполняет fn внутри savepoint'а главной транзакции tx (pgx
// реализует Begin поверх SAVEPOINT). Если fn возвращает ошибку, savepoint
// откатывается, а внешняя транзакция остаётся в рабочем состоянии — это
// единственный способ продолжить импорт следующих строк после, например,
// unique-violation на одной из них. До этого без savepoint первый failed
// INSERT переводил pgx-tx в aborted-state и все последующие запросы падали
// каскадом «current transaction is aborted».
func runInSavepoint(ctx context.Context, tx pgx.Tx, fn func(pgx.Tx) error) error {
	sp, err := tx.Begin(ctx)
	if err != nil {
		return fmt.Errorf("не удалось создать savepoint: %w", err)
	}
	if ferr := fn(sp); ferr != nil {
		_ = sp.Rollback(ctx)
		return ferr
	}
	if cerr := sp.Commit(ctx); cerr != nil {
		return fmt.Errorf("не удалось зафиксировать savepoint: %w", cerr)
	}
	return nil
}

// isNotFound отличает легитимное «строки нет» (pgx.ErrNoRows) от реальной
// ошибки БД (отвалилось соединение, нет таблицы, рассинхрон sqlc/схемы и т.п.).
// Раньше код проверял только `err == nil` и при любой ошибке шёл создавать
// запись — а в pgx это уже после aborted-state, что приводило к каскаду
// мусорных ошибок. Теперь схемные/инфраструктурные ошибки поднимаются наверх
// и останавливают импорт с понятным сообщением.
func isNotFound(err error) bool {
	return errors.Is(err, pgx.ErrNoRows)
}

// Имена листов в шаблоне импорта операций. Лист «Операции» обязателен,
// «Группы» и «Категории» опциональны — без них операции должны ссылаться на
// уже существующие категории.
const (
	sheetOperationsGroups     = "Группы"
	sheetOperationsCategories = "Категории"
	sheetOperationsOperations = "Операции"
)

// Колонки для каждого листа. Резолвятся по нормализованному заголовку с
// синонимами, чтобы перестановка колонок в пользовательском файле не ломала
// импорт молча (см. xlsximport.ResolveColumns).
var (
	importGroupsColumns = []xlsximport.ColumnSpec{
		{Name: "name", Aliases: []string{"Название группы", "Название", "Group", "Имя группы"}, Required: true},
		{Name: "display_order", Aliases: []string{"Порядок отображения", "Порядок", "Order"}},
	}

	importCategoriesColumns = []xlsximport.ColumnSpec{
		{Name: "group", Aliases: []string{"Группа", "Group"}, Required: true},
		{Name: "name", Aliases: []string{"Название категории", "Название", "Category", "Категория"}, Required: true},
		{Name: "prep_cost", Aliases: []string{"Стоимость подготовки", "Подготовка стоимость", "Prep cost"}},
		{Name: "prep_time", Aliases: []string{"Время подготовки", "Подготовка время", "Prep time"}},
	}

	importOperationsColumns = []xlsximport.ColumnSpec{
		{Name: "category", Aliases: []string{"Категория", "Category"}, Required: true},
		{Name: "name", Aliases: []string{"Название операции", "Название", "Operation", "Операция"}, Required: true},
		{Name: "cost", Aliases: []string{"Стоимость", "Цена", "Cost", "Price"}},
		{Name: "time", Aliases: []string{"Время", "Time"}},
		{Name: "thickness_min", Aliases: []string{"Толщина >", "Толщина больше", "Min thickness", "От толщины"}},
		{Name: "thickness_max", Aliases: []string{"Толщина <=", "Толщина меньше или равно", "Толщина <", "Max thickness", "До толщины"}},
		{Name: "formula", Aliases: []string{"Формула", "Formula"}},
		{Name: "material", Aliases: []string{"Материал", "Material"}},
	}
)

// pendingRule — накапливаем намерения создать правила, чтобы прогнать их
// отдельным шагом после импорта самих операций. Это отделяет данные от
// derived-правил: импорт можно повторно прогонять без дубликатов, а шаг
// применения правил в будущем — сделать опциональным.
type pendingRule struct {
	operationID   int32
	operationName string
	rowNumber     int
	materialName  string
	thicknessMin  *float64
	thicknessMax  *float64
	formula       string
	cost          float64
}

// ImportFromXLSX парсит XLSX-файл с операциями и возвращает структурированный
// отчёт (создано / обновлено / пропущено + причины). До этого рефакторинга
// функция возвращала только error и теряла причины пропуска строк (логировала
// в stdout). Колонки резолвятся по заголовкам с синонимами через xlsximport —
// перестановка колонок в пользовательском файле больше не ломает импорт.
//
// Транзакция охватывает всю операцию: либо весь файл лёг в БД (с возможными
// пропусками отдельных строк, см. отчёт), либо ничего. Это важно, потому что
// группы / категории / операции связаны FK; частичный импорт оставлял бы
// висячие ссылки.
//
// Создание правил применимости/ценообразования выделено в отдельный шаг
// (applyRulesFromImport) — derived-данные не смешиваются с сырым импортом.
func (s *OperationService) ImportFromXLSX(ctx context.Context, file io.Reader) (*xlsximport.ImportReport, error) {
	xlsx, err := excelize.OpenReader(file)
	if err != nil {
		return nil, fmt.Errorf("не удалось открыть XLSX: %w", err)
	}
	defer xlsx.Close()

	tx, err := s.pool.Begin(ctx)
	if err != nil {
		return nil, fmt.Errorf("не удалось начать транзакцию: %w", err)
	}
	committed := false
	defer func() {
		if !committed {
			_ = tx.Rollback(ctx)
		}
	}()

	report := &xlsximport.ImportReport{}

	groupMap := make(map[string]int32)
	categoryMap := make(map[string]int32)
	var pendingRules []pendingRule

	if err := s.importGroupsSheet(ctx, xlsx, tx, groupMap, report); err != nil {
		return nil, err
	}
	if err := s.importCategoriesSheet(ctx, xlsx, tx, groupMap, categoryMap, report); err != nil {
		return nil, err
	}
	if err := s.importOperationsSheet(ctx, xlsx, tx, categoryMap, &pendingRules, report); err != nil {
		return nil, err
	}

	if err := tx.Commit(ctx); err != nil {
		return nil, fmt.Errorf("не удалось зафиксировать транзакцию: %w", err)
	}
	committed = true

	// Правила применяются ПОСЛЕ commit'а основной транзакции, потому что
	// rulesService использует pool-соединение (не нашу tx) — до коммита оно
	// просто не видит свежесозданные операции по entity_id. Cleaner-and-recreate
	// для каждой импортированной операции даёт идемпотентность правил и
	// round-trip «убрали thickness из xlsx → правило исчезло».
	s.applyRulesFromImport(ctx, s.queries, pendingRules, report)

	return report, nil
}

func (s *OperationService) importGroupsSheet(
	ctx context.Context,
	xlsx *excelize.File,
	tx pgx.Tx,
	groupMap map[string]int32,
	report *xlsximport.ImportReport,
) error {
	rows, err := xlsx.GetRows(sheetOperationsGroups)
	if err != nil || len(rows) == 0 {
		return nil // лист опционален
	}

	cols, err := xlsximport.ResolveColumns(rows[0], importGroupsColumns)
	if err != nil {
		return fmt.Errorf("лист %q: %w", sheetOperationsGroups, err)
	}

	for i := 1; i < len(rows); i++ {
		rowNum := i + 1 // 1-based для пользователя
		row := rows[i]
		name := xlsximport.Cell(row, cols, "name")
		if name == "" {
			continue
		}

		var displayOrder int32
		if raw := xlsximport.Cell(row, cols, "display_order"); raw != "" {
			v, perr := xlsximport.ParseNumber(raw)
			if perr != nil {
				report.Skip(rowNum, "группа %q: %v", name, perr)
				continue
			}
			displayOrder = int32(v)
		}

		// Поиск существующей — на главной транзакции, чтобы кэшировать ID и
		// сравнить поля. Раньше при матче была безусловная Skip — поэтому
		// display_order, изменённый пользователем в xlsx, не применялся.
		existing, lookupErr := db.New(tx).GetOperationGroupByName(ctx, name)
		if lookupErr == nil {
			groupMap[name] = existing.ID
			// Если xlsx что-то поменял — UPDATE; иначе Skip без лишних запросов.
			if groupNeedsUpdate(existing, name, displayOrder) {
				spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
					_, err := db.New(sp).UpdateOperationGroup(ctx, db.UpdateOperationGroupParams{
						ID:           existing.ID,
						Name:         name,
						DisplayOrder: pgtype.Int4{Int32: displayOrder, Valid: displayOrder > 0},
						Icon:         existing.Icon, // из xlsx не читаем — не затираем
					})
					return err
				})
				if spErr != nil {
					report.Skip(rowNum, "не удалось обновить группу %q: %v", name, spErr)
					continue
				}
				report.Add(xlsximport.RowResult{
					RowNumber: rowNum, Status: xlsximport.StatusUpdated, Entity: name,
				})
				continue
			}
			report.Add(xlsximport.RowResult{
				RowNumber: rowNum, Status: xlsximport.StatusSkipped,
				Entity: name, Reason: "группа уже актуальна",
			})
			continue
		}
		if !isNotFound(lookupErr) {
			// Реальная ошибка БД — не молчим, иначе следующие строки попадут в
			// каскад «current transaction is aborted».
			return fmt.Errorf("проверка группы %q: %w", name, lookupErr)
		}

		// Создание — в savepoint'е, чтобы unique-violation или другая
		// строкоспецифичная ошибка не убивала всю транзакцию.
		var createdID int32
		spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
			g, err := db.New(sp).CreateOperationGroup(ctx, db.CreateOperationGroupParams{
				Name:         name,
				DisplayOrder: pgtype.Int4{Int32: displayOrder, Valid: displayOrder > 0},
			})
			if err != nil {
				return err
			}
			createdID = g.ID
			return nil
		})
		if spErr != nil {
			report.Skip(rowNum, "не удалось создать группу %q: %v", name, spErr)
			continue
		}
		groupMap[name] = createdID
		report.Add(xlsximport.RowResult{
			RowNumber: rowNum, Status: xlsximport.StatusCreated, Entity: name,
		})
	}
	return nil
}

// groupNeedsUpdate — true, если в xlsx изменилось имя или порядок отображения.
// Имя сравниваем тривиально (хотя при матче по имени оно и так совпадает).
// DisplayOrder в xlsx может быть 0 («не задан») — тогда в БД должен быть
// «не задан» (DisplayOrder.Valid=false) или 0; иначе update.
func groupNeedsUpdate(existing db.OperationGroup, name string, displayOrder int32) bool {
	if existing.Name != name {
		return true
	}
	existingOrder := int32(0)
	if existing.DisplayOrder.Valid {
		existingOrder = existing.DisplayOrder.Int32
	}
	return existingOrder != displayOrder
}

func (s *OperationService) importCategoriesSheet(
	ctx context.Context,
	xlsx *excelize.File,
	tx pgx.Tx,
	groupMap map[string]int32,
	categoryMap map[string]int32,
	report *xlsximport.ImportReport,
) error {
	rows, err := xlsx.GetRows(sheetOperationsCategories)
	if err != nil || len(rows) == 0 {
		return nil
	}

	cols, err := xlsximport.ResolveColumns(rows[0], importCategoriesColumns)
	if err != nil {
		return fmt.Errorf("лист %q: %w", sheetOperationsCategories, err)
	}
	q := db.New(tx)

	for i := 1; i < len(rows); i++ {
		rowNum := i + 1
		row := rows[i]
		categoryName := xlsximport.Cell(row, cols, "name")
		if categoryName == "" {
			continue
		}
		groupName := xlsximport.Cell(row, cols, "group")

		groupID, exists := groupMap[groupName]
		if !exists {
			g, gerr := q.GetOperationGroupByName(ctx, groupName)
			if gerr == nil {
				groupID = g.ID
				groupMap[groupName] = groupID
				exists = true
			} else if !isNotFound(gerr) {
				return fmt.Errorf("проверка группы %q: %w", groupName, gerr)
			}
		}
		if !exists {
			report.Skip(rowNum, "категория %q: группа %q не найдена", categoryName, groupName)
			continue
		}

		prepCost, perr := xlsximport.ParseNumber(xlsximport.Cell(row, cols, "prep_cost"))
		if perr != nil {
			report.Skip(rowNum, "категория %q: %v", categoryName, perr)
			continue
		}
		prepTime, perr := xlsximport.ParseNumber(xlsximport.Cell(row, cols, "prep_time"))
		if perr != nil {
			report.Skip(rowNum, "категория %q: %v", categoryName, perr)
			continue
		}

		// Существующая категория — обновляем prep_cost/prep_time/group_id, если
		// что-то отличается. Раньше при матче была безусловная Skip, поэтому
		// пользовательские правки времени/стоимости подготовки в xlsx
		// игнорировались.
		existing, lookupErr := q.GetOperationCategoryByName(ctx, categoryName)
		if lookupErr == nil {
			categoryMap[categoryName] = existing.ID
			if categoryNeedsUpdate(existing, groupID, prepCost, prepTime) {
				spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
					_, err := db.New(sp).UpdateOperationCategory(ctx, db.UpdateOperationCategoryParams{
						ID:       existing.ID,
						GroupID:  pgtype.Int4{Int32: groupID, Valid: true},
						Name:     categoryName,
						PrepCost: s.floatToNumeric(prepCost),
						PrepTime: s.floatToNumeric(prepTime),
						IsActive: pgtype.Bool{Bool: true, Valid: true},
					})
					return err
				})
				if spErr != nil {
					report.Skip(rowNum, "не удалось обновить категорию %q: %v", categoryName, spErr)
					continue
				}
				report.Add(xlsximport.RowResult{
					RowNumber: rowNum, Status: xlsximport.StatusUpdated, Entity: categoryName,
				})
				continue
			}
			report.Add(xlsximport.RowResult{
				RowNumber: rowNum, Status: xlsximport.StatusSkipped,
				Entity: categoryName, Reason: "категория уже актуальна",
			})
			continue
		}
		if !isNotFound(lookupErr) {
			return fmt.Errorf("проверка категории %q: %w", categoryName, lookupErr)
		}

		var createdID int32
		spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
			c, err := db.New(sp).CreateOperationCategory(ctx, db.CreateOperationCategoryParams{
				GroupID:  pgtype.Int4{Int32: groupID, Valid: true},
				Name:     categoryName,
				PrepCost: s.floatToNumeric(prepCost),
				PrepTime: s.floatToNumeric(prepTime),
				IsActive: pgtype.Bool{Bool: true, Valid: true},
			})
			if err != nil {
				return err
			}
			createdID = c.ID
			return nil
		})
		if spErr != nil {
			report.Skip(rowNum, "не удалось создать категорию %q: %v", categoryName, spErr)
			continue
		}
		categoryMap[categoryName] = createdID
		report.Add(xlsximport.RowResult{
			RowNumber: rowNum, Status: xlsximport.StatusCreated, Entity: categoryName,
		})
	}
	return nil
}

// categoryNeedsUpdate — true, если group_id, prep_cost или prep_time из xlsx
// расходятся с тем, что лежит в БД. floatEqual — обычное сравнение с epsilon,
// чтобы 0.10000001 не считалось «изменением» из-за floating-point.
func categoryNeedsUpdate(existing db.OperationCategory, groupID int32, prepCost, prepTime float64) bool {
	existingGroupID := int32(0)
	if existing.GroupID.Valid {
		existingGroupID = existing.GroupID.Int32
	}
	if existingGroupID != groupID {
		return true
	}
	if !floatEqual(numericToFloat(existing.PrepCost), prepCost) {
		return true
	}
	if !floatEqual(numericToFloat(existing.PrepTime), prepTime) {
		return true
	}
	return false
}

func (s *OperationService) importOperationsSheet(
	ctx context.Context,
	xlsx *excelize.File,
	tx pgx.Tx,
	categoryMap map[string]int32,
	pending *[]pendingRule,
	report *xlsximport.ImportReport,
) error {
	rows, err := xlsx.GetRows(sheetOperationsOperations)
	if err != nil {
		return fmt.Errorf("лист %q не найден в файле", sheetOperationsOperations)
	}
	if len(rows) == 0 {
		return fmt.Errorf("лист %q пуст", sheetOperationsOperations)
	}

	cols, err := xlsximport.ResolveColumns(rows[0], importOperationsColumns)
	if err != nil {
		return fmt.Errorf("лист %q: %w", sheetOperationsOperations, err)
	}
	q := db.New(tx)

	for i := 1; i < len(rows); i++ {
		rowNum := i + 1
		row := rows[i]
		opName := xlsximport.Cell(row, cols, "name")
		if opName == "" {
			continue
		}
		categoryName := xlsximport.Cell(row, cols, "category")

		categoryID, exists := categoryMap[categoryName]
		if !exists {
			c, cerr := q.GetOperationCategoryByName(ctx, categoryName)
			if cerr == nil {
				categoryID = c.ID
				categoryMap[categoryName] = categoryID
				exists = true
			} else if !isNotFound(cerr) {
				return fmt.Errorf("проверка категории %q: %w", categoryName, cerr)
			}
		}
		if !exists {
			report.Skip(rowNum, "операция %q: категория %q не найдена", opName, categoryName)
			continue
		}

		// Список существующих операций категории — нужен и для матча, и для
		// обновления (нам нужен ID, чтобы вызвать UpdateOperation).
		existingList, lerr := q.ListOperationsByCategory(ctx, pgtype.Int4{Int32: categoryID, Valid: true})
		if lerr != nil {
			return fmt.Errorf("список операций в категории %q: %w", categoryName, lerr)
		}

		cost, perr := xlsximport.ParseNumber(xlsximport.Cell(row, cols, "cost"))
		if perr != nil {
			report.Skip(rowNum, "операция %q: %v", opName, perr)
			continue
		}
		timeMin, perr := xlsximport.ParseNumber(xlsximport.Cell(row, cols, "time"))
		if perr != nil {
			report.Skip(rowNum, "операция %q: %v", opName, perr)
			continue
		}
		thicknessMin, perr := parseOptionalNumber(xlsximport.Cell(row, cols, "thickness_min"))
		if perr != nil {
			report.Skip(rowNum, "операция %q: %v", opName, perr)
			continue
		}
		thicknessMax, perr := parseOptionalNumber(xlsximport.Cell(row, cols, "thickness_max"))
		if perr != nil {
			report.Skip(rowNum, "операция %q: %v", opName, perr)
			continue
		}
		formula := strings.TrimSpace(xlsximport.Cell(row, cols, "formula"))
		materialName := xlsximport.Cell(row, cols, "material")

		// Главный фикс: при матче по name+category мы теперь не Skip, а UPDATE.
		// Раньше пользовательские правки времени/стоимости в xlsx молча
		// игнорировались — это и есть жалоба «время не меняется».
		if existingOp, found := findOperationByName(existingList, opName); found {
			operationID := existingOp.ID
			needsUpdate := operationNeedsUpdate(existingOp, cost, timeMin)
			if needsUpdate {
				spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
					_, err := db.New(sp).UpdateOperation(ctx, db.UpdateOperationParams{
						ID:                 operationID,
						Name:               opName,
						Cost:               s.floatToNumeric(cost),
						Time:               s.floatToNumeric(timeMin),
						IsActive:           pgtype.Bool{Bool: true, Valid: true},
						IsOneTimeOperation: existingOp.IsOneTimeOperation, // флаг не в xlsx — не трогаем
					})
					return err
				})
				if spErr != nil {
					report.Skip(rowNum, "не удалось обновить операцию %q: %v", opName, spErr)
					continue
				}
				report.Add(xlsximport.RowResult{
					RowNumber: rowNum, Status: xlsximport.StatusUpdated, Entity: opName,
				})
			} else {
				report.Add(xlsximport.RowResult{
					RowNumber: rowNum, Status: xlsximport.StatusSkipped,
					Entity: opName, Reason: "операция уже актуальна",
				})
			}
			// ВАЖНО: правила пересоздаются ВСЕГДА (и для UPDATE, и для Skip),
			// потому что в xlsx могли поменять только thickness/material/formula.
			// applyRulesFromImport сначала удалит старые правила этой операции,
			// потом создаст новые — это даёт идемпотентность и чистый round-trip
			// (убрали материал в xlsx → правило исчезло из БД).
			*pending = append(*pending, pendingRule{
				operationID:   operationID,
				operationName: opName,
				rowNumber:     rowNum,
				materialName:  materialName,
				thicknessMin:  thicknessMin,
				thicknessMax:  thicknessMax,
				formula:       formula,
				cost:          cost,
			})
			continue
		}

		// Не нашли — создаём.
		var createdID int32
		spErr := runInSavepoint(ctx, tx, func(sp pgx.Tx) error {
			op, err := db.New(sp).CreateOperation(ctx, db.CreateOperationParams{
				CategoryID: pgtype.Int4{Int32: categoryID, Valid: true},
				Name:       opName,
				Cost:       s.floatToNumeric(cost),
				Time:       s.floatToNumeric(timeMin),
				IsActive:   pgtype.Bool{Bool: true, Valid: true},
			})
			if err != nil {
				return err
			}
			createdID = op.ID
			return nil
		})
		if spErr != nil {
			report.Skip(rowNum, "не удалось создать операцию %q: %v", opName, spErr)
			continue
		}
		report.Add(xlsximport.RowResult{
			RowNumber: rowNum, Status: xlsximport.StatusCreated, Entity: opName,
		})

		// Правила нового объекта добавляем всегда (даже если xlsx пустой):
		// applyRulesFromImport сам решит, создавать ли что-то — и логика
		// одинаковая для новых и существующих операций.
		*pending = append(*pending, pendingRule{
			operationID:   createdID,
			operationName: opName,
			rowNumber:     rowNum,
			materialName:  materialName,
			thicknessMin:  thicknessMin,
			thicknessMax:  thicknessMax,
			formula:       formula,
			cost:          cost,
		})
	}
	return nil
}

// findOperationByName возвращает операцию по точному совпадению имени.
// Заменяет старый isDuplicate (он возвращал только bool, без ID).
func findOperationByName(list []db.Operation, name string) (db.Operation, bool) {
	for _, op := range list {
		if op.Name == name {
			return op, true
		}
	}
	return db.Operation{}, false
}

// operationNeedsUpdate — есть ли расхождение между БД и xlsx-значениями
// cost/time. Если ничего не поменялось — UPDATE можно не делать (не тревожим БД,
// в отчёте идёт Skipped «уже актуальна»).
func operationNeedsUpdate(existing db.Operation, cost, timeMin float64) bool {
	if !floatEqual(numericToFloat(existing.Cost), cost) {
		return true
	}
	if !floatEqual(numericToFloat(existing.Time), timeMin) {
		return true
	}
	return false
}

// applyRulesFromImport идемпотентно синхронизирует правила операций с xlsx:
//
//   1. Для каждой импортированной операции (новой ИЛИ существующей) сначала
//      удаляются ВСЕ её существующие unified-правила. Это устраняет старый
//      баг «при ре-импорте правила плодятся», и одновременно даёт правильный
//      round-trip «удалил материал/формулу в xlsx → правило исчезло».
//   2. Затем по данным из xlsx создаются правила применимости (если задан
//      материал или диапазон толщины) и ценообразования (если задана формула).
//      Если все три поля пусты — операция остаётся без правил. Это норма.
//
// Вызывается ПОСЛЕ tx.Commit основной транзакции (см. ImportFromXLSX): правила
// пишутся через s.rulesService.db (пул), и до коммита он не видит только что
// вставленные операции по их ID. Возможные ошибки правил уже не влияют на
// данные операций — операции уже сохранены.
func (s *OperationService) applyRulesFromImport(
	ctx context.Context,
	queries *db.Queries,
	pending []pendingRule,
	report *xlsximport.ImportReport,
) {
	for _, p := range pending {
		entityID := pgtype.Int4{Int32: p.operationID, Valid: true}
		if err := queries.DeleteOperationRulesByEntityID(ctx, entityID); err != nil {
			report.Skip(p.rowNumber, "не удалось очистить старые правила %q: %v", p.operationName, err)
			continue
		}

		if p.materialName != "" || p.thicknessMin != nil || p.thicknessMax != nil {
			if err := s.createApplicabilityRule(ctx, p.operationID, p.operationName, p.materialName, p.thicknessMin, p.thicknessMax, queries); err != nil {
				report.Skip(p.rowNumber, "правило применимости для %q: %v", p.operationName, err)
				continue
			}
		}
		if p.formula != "" {
			if err := s.createPricingRule(ctx, p.operationID, p.operationName, p.formula, p.cost, queries); err != nil {
				report.Skip(p.rowNumber, "правило ценообразования для %q: %v", p.operationName, err)
				continue
			}
		}
		// В отчёте удачное применение правил для операции не дублируем
		// отдельной строкой — операция уже отражена выше как Created/Updated.
	}
}

func parseOptionalNumber(raw string) (*float64, error) {
	if strings.TrimSpace(raw) == "" {
		return nil, nil
	}
	v, err := xlsximport.ParseNumber(raw)
	if err != nil {
		return nil, err
	}
	return &v, nil
}

