// Smoke-проверка импорта операций из xlsx. Запускается вручную:
//   go run ./cmd/test_op_import <path-to.xlsx>
//
// Выводит ImportReport со всеми пропусками — полезно для воспроизведения
// багов на конкретном пользовательском файле.
package main

import (
	"context"
	"fmt"
	"log"
	"os"

	"github.com/jackc/pgx/v5/pgxpool"

	"v-calc/internal/config"
	"v-calc/internal/service"
	"v-calc/internal/service/formula"
	"v-calc/internal/service/rules"
	"v-calc/internal/shared"
)

func main() {
	if len(os.Args) < 2 {
		log.Fatal("usage: test_op_import <file.xlsx>")
	}
	path := os.Args[1]

	cfg, err := config.NewConfig()
	if err != nil {
		log.Fatalf("config: %v", err)
	}
	ctx := context.Background()
	pool, err := pgxpool.New(ctx, cfg.Database.GetDSN())
	if err != nil {
		log.Fatalf("db: %v", err)
	}
	defer pool.Close()

	formulaService := formula.NewService(pool)
	rulesService := rules.NewService(pool, formulaService, shared.NewLogger())
	op := service.NewOperationService(pool, rulesService)

	f, err := os.Open(path)
	if err != nil {
		log.Fatalf("open: %v", err)
	}
	defer f.Close()

	report, err := op.ImportFromXLSX(ctx, f)
	if err != nil {
		log.Printf("import returned error: %v", err)
	}
	if report != nil {
		fmt.Printf("Created=%d Updated=%d Skipped=%d\n", report.Created, report.Updated, report.Skipped)
		for _, r := range report.Rows {
			if r.Status == "skipped" {
				fmt.Printf("  стр.%d skipped: %s\n", r.RowNumber, r.Reason)
			}
		}
	}
}

