package service

// Тест reverse-маппинга правил → derived поля для xlsx-экспорта операций.
// Защищает от регрессии вида «толщины/материалы пропадают в экспорте» —
// именно она была после первой реализации, когда я искал данные внутри
// Actions.Applicability[0].Condition, а createApplicabilityRule пишет их в
// корневом Conditions.Material.

import (
	"testing"

	"v-calc/internal/service/rules"
)

func TestDerivedFieldsFromRules_ApplicabilityAndPricing(t *testing.T) {
	thMin, thMax := 0.5, 3.0
	matID := int32(42)
	// Имитация двух правил, как их создаёт importOperationsSheet: одно с
	// материалом+толщиной (createApplicabilityRule) — данные в КОРНЕ
	// Conditions.Material; другое с формулой (createPricingRule) — формула
	// в Actions.Pricing[0].Formula.
	input := []rules.OperationRuleDTO{
		{
			RuleType: "unified_operation_rule",
			Conditions: rules.RuleConditions{
				Material: &rules.MaterialCondition{
					ID:        []int32{matID},
					Thickness: &rules.RangeCondition{Min: &thMin, Max: &thMax},
				},
			},
			Actions: rules.RuleActions{
				Applicability: []rules.ConditionalAction{
					{ID: "auto-generated-applicability", Formula: "true"},
				},
			},
		},
		{
			RuleType: "unified_operation_rule",
			Actions: rules.RuleActions{
				Pricing: []rules.ConditionalAction{
					{ID: "auto-generated-pricing", Formula: "perimeter * 100"},
				},
			},
		},
	}

	tmin, tmax, mid, formula := derivedFieldsFromRules(input)
	if tmin == nil || *tmin != 0.5 {
		t.Errorf("thicknessMin: got %v, want 0.5", tmin)
	}
	if tmax == nil || *tmax != 3.0 {
		t.Errorf("thicknessMax: got %v, want 3.0", tmax)
	}
	if mid == nil || *mid != matID {
		t.Errorf("materialID: got %v, want %d", mid, matID)
	}
	if formula != "perimeter * 100" {
		t.Errorf("formula: got %q, want %q", formula, "perimeter * 100")
	}
}

func TestDerivedFieldsFromRules_NoRules(t *testing.T) {
	tmin, tmax, mid, formula := derivedFieldsFromRules(nil)
	if tmin != nil || tmax != nil || mid != nil || formula != "" {
		t.Errorf("ожидали пустые значения, получили tmin=%v tmax=%v mid=%v formula=%q",
			tmin, tmax, mid, formula)
	}
}

func TestDerivedFieldsFromRules_FormulaTrueIgnored(t *testing.T) {
	// «true» из applicability не должна попадать в поле формулы — это
	// служебный маркер createApplicabilityRule, не пользовательская формула.
	input := []rules.OperationRuleDTO{
		{
			Actions: rules.RuleActions{
				Applicability: []rules.ConditionalAction{
					{ID: "auto-generated-applicability", Formula: "true"},
				},
			},
		},
	}
	_, _, _, formula := derivedFieldsFromRules(input)
	if formula != "" {
		t.Errorf("applicability «true» не должна утекать в formula, got %q", formula)
	}
}

